INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Flow Cytometry', 'Flow cytometry is a laser-based, high-throughput single-cell analysis technique used to simultaneously measure multiple physical and fluorescent characteristics of cells or particles in suspension. This assay quantifies cell populations based on parameters such as cell size (forward scatter), granularity (side scatter), and fluorescence intensity of labeled surface or intracellular markers, enabling immunophenotyping, cell cycle analysis, viability assessment, and functional studies. Samples are typically prepared as single-cell suspensions, stained with fluorochrome-conjugated antibodies or dyes, and acquired on a flow cytometer, with subsequent data analysis performed using dedicated software (e.g., FlowJo, FCS Express) to gate and enumerate distinct cellular subpopulations. The "Data Linked" designation indicates that the assay results are associated with externally referenced or linked datasets, facilitating integrated analysis across experimental cohorts or studies.', 'flow cytometry, FACS, immunophenotyping, cell surface marker staining, fluorescence cytometry, multi-parameter cell analysis, cell population profiling', NULL, 'TIS or CEX or CEL, AB or ABP', 'D.FCS', 'D.FLOW', 'Processed', 'Raw', '(insert link here)', 'Immport (link)', 'TIS::Type, ABP::Parent, D.FLOW::Stimulation, D.FLOW::Protocol, D.FLOW::Parent', 'strip beginning and end of the protocols, give it phrases and not IDs', NULL, 30);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gene Expression Analysis', 'Gene expression analysis converts raw sequencing reads into quantified transcript abundance. It involves aligning reads to a reference genome or transcriptome, followed by normalization and quality control.\nInput: Sequencing file (e.g., FASTQ / D.SEQ) Output: Processed expression matrices and summary statistics.', 'RNA-seq analysis, differential expression analysis, DESeq2, edgeR, count matrix processing, transcriptomics analysis, STAR kallisto salmon', NULL, 'D.SEQ', NULL, 'A.GEX', 'Raw', 'Analyzed', '(insert link here)', 'GEO', 'A.GEX::Parent, A.GEX::Protocol', NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('RNA Extraction', 'RNA extraction is a laboratory procedure used to isolate and purify total RNA from biological samples, serving as a foundational step for downstream transcriptomic analyses such as RNA sequencing, RT-PCR, or microarray profiling. The process typically involves cell lysis, denaturation of protein-RNA complexes, and purification using methods such as phenol-chloroform extraction, silica column-based kits, or magnetic bead-based approaches to yield high-quality RNA free of DNA, protein, and other contaminants. Key quality metrics assessed during and after extraction include RNA integrity number (RIN), A260/A280 and A260/A230 absorbance ratios, and RNA concentration, which are commonly measured using instruments such as a NanoDrop spectrophotometer or Bioanalyzer. Proper sample handling, including maintenance of an RNase-free environment and cold-chain integrity, is critical to preserving RNA quality and ensuring reproducibility across experimental conditions.', 'RNA isolation, RNA purification, total RNA extraction, Trizol extraction, column RNA extraction, RNA integrity RIN, RNA isolation kit', 'RNA Isolation', 'TIS or CEX or CEL', NULL, 'RNA', 'Processed', 'Processed', '(insert link here)', NULL, 'RNA::RIN, RNA::Protocol, RNA::Parent', NULL, NULL, 61);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Sequencing', 'Single cell sequencing generates sequencing data from individual cells within a mixed population. The assay involves capturing or barcoding single cells, amplifying nucleic acids, and sequencing the resulting libraries.\nInput: Single-cell DNA/RNA sample Output: Sequencing file (e.g., FASTQ / D.SEQ) containing cell-resolved read data.', 'scRNA-seq, 10x Genomics, single cell sequencing, droplet-based sequencing, cell barcoding, scATAC-seq, single cell NGS', NULL, 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', '(insert link here)', 'Single Cell Atlas', 'D.SEQ::LibraryStrategy, D.SEQ::LibrarySource, D.SEQ::LibrarySelection', NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Collection', 'This assay captures metadata associated with tissue collection procedures, documenting critical provenance and contextual information for biological specimens obtained from study subjects. It records standardized parameters such as tissue type, anatomical source, collection method, preservation conditions, and relevant donor or sample identifiers to ensure traceability and reproducibility across downstream experimental workflows. This metadata serves as a foundational record linking collected tissues to subsequent analytical assays, enabling proper data integration, quality control, and interpretation of results within the broader research study.', 'tissue harvest, biopsy collection, tissue sampling, specimen collection, organ harvest, tissue extraction, sample collection', 'Tissue Extraction', 'MUS or PAV', NULL, 'TIS', 'Source', 'Processed', '(insert link here)', NULL, 'TIS::Parent, TIS::Type', NULL, NULL, 74);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Absorption and Emission Spectroscopy', 'Absorption and emission spectroscopy measures the interaction between light and a sample to assess molecular properties. The assay detects absorbed or emitted light at specific wavelengths to characterize compounds or biomolecules.\nInput: Chemical or biological sample Output: Spectral data file containing absorbance or emission intensity profiles.', 'UV-Vis spectroscopy, fluorescence spectroscopy, emission spectroscopy, absorption spectroscopy, optical spectroscopy, spectrophotometry, excitation emission measurement', NULL, 'CHM', NULL, 'D.SPC', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Absorption and Emission Spectroscopy Analysis', 'Absorption and emission spectroscopy analysis processes raw spectral data to identify and quantify molecular features. It involves baseline correction, peak fitting, and normalization to generate interpretable spectra.\nInput: Spectral data file Output: Processed absorption or emission profiles and quantitative summaries.', 'spectral analysis, absorbance analysis, emission analysis, UV-Vis analysis, fluorescence data processing, peak fitting, baseline correction', NULL, 'D.SPC', NULL, 'A.SPC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Agglutination Assay', 'An agglutination assay is an immunological technique that detects and quantifies antibody-antigen interactions through visible particle clumping (agglutination). The assay works by mixing serial dilutions of antiserum with target particles — which may be bacteria, red blood cells coated with antigens, or latex beads conjugated to specific analytes. After incubation, agglutination is assessed visually or by turbidimetric measurement: agglutinated samples show dispersed mats or granular clumping, while non-agglutinated samples form tight pellets. Results are typically reported as agglutination titers (the highest dilution producing visible clumping) scored on a scale from +1 (weak) to +4 (strong). Agglutination assays are used to quantify antibody titers, identify immune responses to bacterial or viral antigens, and serve as diagnostic tools in immunology and microbiology. Reference: https://cmdr.ubc.ca/bobh/method/agglutination-assays/', 'agglutination, hemagglutination, latex agglutination, antigen-antibody clumping, particle agglutination, serological titer, turbidimetric assay', NULL, 'CHM', NULL, 'D.IMG', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 1);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Analyzed Spatial Proteomics', 'Spatial proteomics is a methodology that maps the distribution, abundance, and localization of proteins within tissue sections or cellular compartments while preserving spatial context. This assay typically employs imaging-based platforms such as multiplex immunofluorescence, imaging mass cytometry (IMC), or Digital Spatial Profiling (DSP) to simultaneously detect and quantify multiple protein targets at defined spatial coordinates. Sample preparation generally involves formalin-fixed paraffin-embedded (FFPE) or fresh-frozen tissue sections subjected to antigen retrieval, antibody staining or metal-conjugated probe hybridization, followed by high-resolution image acquisition and computational analysis to deconvolve protein expression patterns across tissue microenvironments. The resulting spatially resolved proteomic data enables characterization of cell phenotypes, cell-cell interactions, and tissue architecture in the context of disease states or biological processes.', 'spatial proteomics analysis, Digital Spatial Profiling, DSP analysis, multiplex immunofluorescence analysis, IMC analysis, imaging mass cytometry analysis, spatial protein mapping', NULL, 'D.MSP', NULL, 'A.MSP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 2);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Treatment', 'An antibody treatment assay exposes biological samples or model organisms to specific antibodies to induce or modulate a response. It is used to study therapeutic efficacy, immune regulation, or target engagement.\nInput: Biological system or culture Output: Treated sample or response dataset reflecting antibody effects.', 'antibody challenge, antibody depletion, antibody administration, passive immunization, antibody infusion, antibody exposure', 'Antibody Challenge, Antibody Depletion', 'AB', NULL, 'MUS or NHP', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Dependent Complement Deposition', 'An antibody dependent complement deposition assay measures complement activation following antibody binding. The process detects deposition of complement proteins as an indicator of antibody-mediated immune function.\nInput: Antibody-treated target cells or particles Output: Complement deposition data file or fluorescence readout.', 'ADCD, complement deposition assay, C3 deposition, complement activation, opsonization complement, antibody complement fixing', NULL, 'TIS and AB', NULL, 'D.ADCD', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Dependent Functional Profiling', 'Antibody dependent functional profiling evaluates multiple immune effector activities triggered by antibodies. The assay integrates data from complement activation, phagocytosis, and cytotoxicity measurements to define immune functionality.\nInput: Antibody-containing biological sample Output: Functional profiling data representing combined antibody responses.', 'ADFP, antibody effector function, systems serology, functional immune profiling, Fc effector profiling, humoral immune function', 'Antibody Functional Profiling', 'TIS and AB', NULL, 'D.AD**', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Functional Profiling Analysis', 'Antibody functional profiling analysis processes raw functional data to quantify and compare antibody responses. It includes normalization, clustering, and visualization to identify immune activity patterns.\nInput: Raw antibody functional profiling data Output: Processed immune response metrics and comparative profiles.', 'antibody profiling analysis, systems serology analysis, Fc function analysis, immune effector function analysis', NULL, 'D.AD**', NULL, 'A.AD**', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Titer', 'An antibody titer assay determines the concentration of antibodies in a sample through serial dilution and detection. The process measures the dilution at which a detectable signal is maintained to assess immune strength.\nInput: Serum or antibody-containing sample Output: Quantitative antibody titer value.', 'antibody titer, serology titer, ELISA titer, binding titer, endpoint dilution titer, antibody quantification, immunoglobulin measurement', 'Titer Assay', 'TIS', NULL, 'D.TITR', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
