INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Cellular Phagocytosis', 'Antibody-dependent cellular phagocytosis measures immune cell uptake of antibody-coated targets. The assay quantifies phagocytic activity as an indicator of antibody function and cellular response.\nInput: Antibody-treated target cells and effector cells Output: Phagocytosis data file (e.g., fluorescence or imaging-based readouts).', 'ADCP, phagocytosis assay, opsonophagocytosis, THP-1 phagocytosis, monocyte phagocytosis, bead uptake assay, antibody-mediated phagocytosis', NULL, 'TIS and AB', NULL, 'D.ADCP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Cellular Phagocytosis Analysis', 'Antibody-dependent cellular phagocytosis analysis processes raw uptake data to quantify immune cell activity. It calculates phagocytic scores, normalizes results, and generates comparative summaries.\nInput: Raw phagocytosis data Output: Processed activity metrics and visualized response profiles.', 'ADCP analysis, phagocytosis data analysis, opsonophagocytosis analysis, phagocytic score analysis', NULL, 'D.ACDP', NULL, 'A.ADCP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
