INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Neutrophil Phagocytosis', 'Antibody-dependent neutrophil phagocytosis evaluates antibody-mediated uptake of targets by neutrophils. It measures fluorescence or imaging-based signals to assess innate immune activity.\nInput: Antibody-labeled target cells and neutrophils Output: Phagocytosis data file indicating neutrophil uptake efficiency.', 'ADNP, neutrophil phagocytosis, granulocyte phagocytosis, antibody-mediated neutrophil uptake, innate immune effector', NULL, 'TIS and AB', NULL, 'D.ADNP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
