INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent NK Cell Activation Analysis', 'Antibody-dependent NK cell activation analysis processes activation readouts to quantify NK cell responses. It compiles signal intensities or cytokine levels to compare antibody-mediated activation across conditions.\nInput: Raw NK cell activation data Output: Processed activation summaries and response metrics.', 'ADNKA analysis, NK cell activation analysis, ADCC analysis, cytokine secretion analysis, NK degranulation analysis', NULL, 'D.ANDKA', NULL, 'A.ADNKA', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Atomic Force Microscopy', 'Atomic force microscopy captures nanoscale surface features by scanning a probe across a sample’s surface. The assay generates topographical maps used to study morphology, stiffness, or molecular interactions.\nInput: Prepared biological or material sample Output: AFM image data file containing surface topography measurements.', 'AFM, atomic force microscopy, nanoscale imaging, surface topography, force spectroscopy, nanoindentation, cantilever scanning', NULL, 'SNSR', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bacterial Challenge', 'A bacterial challenge assay exposes biological samples or model organisms to a defined bacterial strain. It is used to study infection dynamics, host-pathogen interactions, or immune response under controlled conditions.\nInput: Biological system or culture Output: Treated sample or response dataset reflecting bacterial exposure effects.', 'bacterial infection, pathogen challenge, bacterial inoculation, infection model, microbial challenge, in vivo infection', 'Pathogen Challenge', 'BAC', NULL, 'MUS or NHP', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
