INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bulk DNA Sequencing', 'Bulk DNA sequencing is a high-throughput genomic assay that measures DNA sequence information across a population of cells simultaneously, capturing the aggregate genetic landscape of a sample without single-cell resolution. This method typically involves extraction and fragmentation of genomic DNA, library preparation (including adapter ligation and optional target enrichment or amplification), and sequencing on next-generation sequencing (NGS) platforms such as Illumina instruments. The resulting sequence reads are aligned to a reference genome and analyzed bioinformatically to identify genetic variants, structural alterations, copy number changes, or other genomic features present within the bulk cell population.', 'WGS, whole genome sequencing, WES, whole exome sequencing, bulk sequencing, population-level sequencing, NGS DNA sequencing', NULL, 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 188);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cancer Cell Extravasation Analysis', 'This assay quantifies the extravasation capacity of cancer cells, measuring their ability to migrate across endothelial barriers as a model of hematogenous metastasis. Using linked experimental data, the assay tracks the transmigration of cancer cells through endothelial monolayers under controlled conditions, capturing key parameters such as the number and rate of cells that successfully breach the vascular barrier. Results are analyzed to provide quantitative metrics of invasive potential, supporting the study of metastatic mechanisms and the evaluation of potential anti-metastatic interventions.', 'extravasation analysis, metastasis assay analysis, transendothelial migration analysis, vascular barrier analysis, invasion analysis, tumor cell motility analysis', NULL, 'D.IMG', NULL, 'A.CCE', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 79);
