INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Culture Imaging', 'Cell culture imaging captures visual data of cultured cells to assess morphology, growth, or behavior. The assay uses microscopy or automated imaging systems to record changes over time.\nInput: Cultured cells Output: Image data or time-lapse files representing cellular structure and activity.', 'cell microscopy, culture imaging, time-lapse cell imaging, live cell culture imaging, brightfield imaging, phase contrast imaging', 'Cell Imaging', 'CEL', NULL, 'D.IMG', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
