INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Extraction', 'Cell extraction isolates intact cells from tissues or biological mixtures for downstream analysis. It uses mechanical or enzymatic dissociation to generate a viable cell suspension.\nInput: Tissue or mixed biological sample Output: Isolated cell suspension suitable for culture or analysis.', 'cell isolation, cell dissociation, cell extraction, tissue dissociation, enzymatic dissociation, single cell suspension', 'Cell Isolation', 'CEL or TIS', NULL, 'CEL or CEX', 'Processed', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Line Creation', 'Cell line creation encompasses the processes used to establish stable or transient cell populations derived from primary tissues, immortalization procedures, or genetic engineering strategies for use in downstream biological assays. This workflow typically involves transfection or transduction of target constructs, selection under appropriate antibiotic or fluorescent marker pressure, single-cell cloning, and expansion of confirmed clones. Resulting cell lines are characterized for expression of relevant transgenes or endogenous targets, genomic integrity, and phenotypic stability prior to use in functional studies. These engineered or adapted cell populations serve as reproducible biological reagents for a broad range of in vitro experimental applications.', 'cell line establishment, cell immortalization, stable line generation, transfection, clonal selection, cell engineering', NULL, 'MUS or TIS', NULL, 'CEL', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, 97);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Lysate', 'Cell lysis breaks open cells to release proteins, nucleic acids, and other intracellular components. The lysate is used for downstream biochemical or molecular assays.\nInput: Cultured or isolated cells Output: Cell lysate containing extracted biomolecules.', 'cell lysis, lysate preparation, cellular homogenate, intracellular protein release, mechanical lysis, detergent lysis', NULL, 'CEL', NULL, 'LYS', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Sorting', 'Cell sorting is a flow cytometry-based assay used to physically separate heterogeneous cell populations into distinct subpopulations based on specific cell surface or intracellular markers, enabling downstream functional, molecular, or phenotypic analyses. Cells are labeled with fluorescently conjugated antibodies or dyes, interrogated by laser excitation, and individually sorted into collection vessels using electrostatic deflection or microfluidic mechanisms according to predefined gating strategies. This dataset represents cell sorting results that are linked to associated experimental or clinical data, facilitating integrative analyses across multiple assay types or study endpoints.', 'FACS, fluorescence-activated cell sorting, cell sorting, flow-based cell separation, electrostatic deflection sorting, cell fractionation', 'Fluorescence-Activated Cell Sorting', 'TIS', 'D.FLOW', 'CEL', 'Processed', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, 13);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Viability', 'A cell viability assay measures the proportion of living cells within a population following treatment or culture. It assesses metabolic activity, membrane integrity, or dye exclusion to determine survival rate.\nInput: Cultured or treated cells Output: Viability data or quantitative survival measurement.', 'viability assay, cytotoxicity assay, cell survival, cell death assessment, metabolic activity assay, proliferation assay', NULL, 'CEL', NULL, 'D.VIA', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical challenge', 'This assay evaluates the biological response of source samples — such as those derived from murine (MUS) or non-human primate (NHP) models — following controlled exposure to a defined chemical agent. The challenge involves administering a test compound to the biological source material under', 'chemical exposure, drug challenge, compound treatment, small molecule challenge, chemical administration, toxicity challenge', NULL, 'CHM', NULL, 'MUS or NHP', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, 14);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical Simulations', 'Chemical simulations use computational modeling to predict molecular behavior and interactions. The process applies physical and chemical principles to estimate reaction outcomes or binding affinities.\nInput: Molecular or compound parameters Output: Simulated dataset describing chemical interactions or energy states.', 'computational chemistry, molecular simulation, in silico chemistry, DFT simulation, molecular dynamics, reaction energy calculation', NULL, 'CHM', NULL, 'D.SIM', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical Synthesis', 'Chemical synthesis combines reagents under controlled conditions to produce specific compounds or molecules. The assay focuses on generating pure and reproducible products for experimental or analytical use.\nInput: Chemical precursors or reagents Output: Synthesized compound or purified chemical sample.', 'organic synthesis, compound synthesis, chemical preparation, drug synthesis, synthetic chemistry, reaction product, reagent preparation', NULL, 'CHM', NULL, 'CHM', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chromatin Sequencing Analysis', 'Chromatin sequencing analysis is a genomic assay that interrogates the structural and regulatory landscape of chromatin by sequencing DNA associated with specific chromatin states, protein binding sites, or accessibility regions. This approach typically employs next-generation sequencing (NGS) technologies following chromatin preparation steps such as immunoprecipitation (ChIP-seq), transposase-based accessibility profiling (ATAC-seq), or nuclease digestion (MNase-seq or FAIRE-seq), depending on the specific application. The resulting sequencing data are computationally processed through alignment, peak calling, and downstream statistical analyses to identify genomic loci associated with transcription factor binding, histone modifications, or open chromatin regions. This assay provides high-resolution, genome-wide maps of chromatin organization that are linked to functional regulatory elements and gene expression data.', 'ATAC-seq analysis, ChIP-seq analysis, chromatin accessibility analysis, epigenomics analysis, histone modification analysis, open chromatin analysis, regulatory element mapping', NULL, 'D.SEQ', NULL, 'A.CHRM', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 16);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CITESEQ Analysis', 'CITE-seq analysis processes multimodal single-cell data combining RNA sequencing and antibody-derived tags. It integrates transcriptomic and surface protein profiles to classify cell types and states.\nInput: Raw CITE-seq data Output: Processed expression matrices and integrated cell-type annotations.', 'CITE-seq analysis, multimodal single cell analysis, ADT RNA integration, surface protein expression analysis, multiomics single cell', NULL, 'D.SEQ', NULL, 'A.SCXP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Clot Modeling Analysis', 'This assay employs computational clot modeling analysis to characterize the mechanical and structural properties of blood clots by integrating linked experimental datasets. The approach combines empirical measurements with mathematical or simulation-based frameworks to quantify parameters such as clot stiffness, fibrin network architecture, viscoelastic behavior, and thrombus formation kinetics. Data linkage enables cross-referencing of multiple input variables — which may include rheological, imaging, or biochemical measurements — to generate holistic models of clot development and stability. Results support the investigation of coagulation disorders, therapeutic interventions, and hemostatic function across diverse patient populations or experimental conditions.', 'clot analysis, coagulation modeling, fibrin network analysis, blood clot mechanics, thrombus analysis, viscoelastic clot analysis', NULL, 'D.IMG', NULL, 'A.CLOT', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 83);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Comet Chip', 'A comet chip assay measures DNA strand breaks by electrophoretic separation of nuclear material within microfabricated wells. It visualizes DNA migration patterns to assess genotoxicity or repair efficiency.\nInput: Treated or control cell samples Output: Comet chip imaging data showing DNA damage profiles.', 'comet assay, single cell gel electrophoresis, DNA damage assay, genotoxicity assay, DNA strand break measurement, tail moment', NULL, 'TIS or CEL or MUS or CHM', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Comet Chip Analysis', 'Comet chip analysis quantifies DNA damage from imaging data collected in comet chip assays. It calculates tail length, moment, and intensity metrics to compare sample damage levels.\nInput: Raw comet chip imaging data Output: Processed DNA damage metrics and visual summaries.', 'comet chip analysis, DNA damage quantification, tail length analysis, tail moment analysis, comet image analysis, genotoxicity analysis', NULL, 'D.IMG', NULL, 'A.COMC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Copy Number Variation Analysis', 'Copy Number Variation (CNV) analysis is performed using bulk DNA sequencing to detect and quantify genomic amplifications, deletions, and other structural alterations across the genome. Genomic DNA is extracted from bulk cell populations, subjected to library preparation, and sequenced using high-throughput next-generation sequencing (NGS) platforms. Sequencing read depth and coverage uniformity are analyzed computationally to identify regions of aberrant copy number relative to a reference, enabling the characterization of somatic or germline CNVs at a genome-wide scale.', 'CNV analysis, copy number alteration, CNA, genomic amplification deletion, structural variant, somatic copy number, genome-wide copy number', NULL, 'D.SEQ', NULL, 'A.CNV', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 20);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Crystallography', 'Crystallography determines molecular or atomic structures by analyzing diffraction patterns from crystallized samples. The assay provides 3D models that reveal spatial arrangement and bonding.\nInput: Crystallized biological or chemical sample Output: Diffraction data and derived structural model files.', 'X-ray crystallography, crystal structure determination, diffraction analysis, single crystal XRD, Bragg diffraction, 3D molecular structure', 'Single-crystal X-ray Crystallography', 'CHM', NULL, 'D.CRY', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CyCIF', 'Cyclic immunofluorescence (CyCIF) sequentially stains and images tissue sections to measure multiple protein markers. The assay captures high-resolution spatial patterns of protein expression.\nInput: Tissue section or fixed cell sample Output: Multiplexed fluorescence imaging data.', 'cyclic immunofluorescence, CyCIF, multiplexed tissue imaging, iterative IF staining, t-CyCIF, tissue cyclic staining', NULL, 'TIS and AB or ABP', NULL, 'D.CYCF', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('cyCIF Analysis', 'Cyclic immunofluorescence (CyCIF) is a multiplexed imaging assay that enables sequential, quantitative detection of numerous protein targets within intact tissue sections or cultured cells through iterative rounds of fluorescent antibody staining, imaging, and signal inactivation. Each cycle involves the application of a panel of fluorophore-conjugated primary or secondary antibodies, followed by wide-field or confocal fluorescence microscopy imaging, and subsequent chemical bleaching or inactivation of fluorescent signals to permit successive rounds of staining on the same sample. Raw multichannel images from each cycle are computationally registered, stitched, and overlaid to generate a single high-dimensional dataset, which is then subjected to cell segmentation and single-cell feature extraction to quantify protein expression, co-expression patterns, and spatial relationships at the single-cell level. This approach allows simultaneous profiling of cell identity, functional state, and tissue architecture across dozens of markers within a spatially resolved context.', 'cyCIF analysis, cyclic immunofluorescence analysis, multiplexed imaging analysis, iterative IF analysis, spatial protein quantification, tissue IF cycling', NULL, 'D.CYCF', NULL, 'A.CYCF', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 180);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CyTOF', 'Cytometry by Time of Flight (CyTOF) is a mass spectrometry-based single-cell analysis platform that enables simultaneous quantification of dozens of protein markers at the single-cell level by labeling antibodies with isotopically pure heavy metal tags rather than fluorescent dyes, thereby eliminating spectral overlap limitations inherent to conventional flow cytometry. Individual cells are introduced into an inductively coupled plasma ion source, vaporized and ionized, and the resulting metal isotope signals are detected and quantified by a time-of-flight mass spectrometer, providing precise measurements of marker expression across large cell populations. This technology is particularly suited for deep immunophenotyping, functional protein analysis, and characterization of complex cellular heterogeneity in samples such as peripheral blood, bone marrow, and tumor-infiltrating immune cells, supporting high-dimensional data analysis workflows including dimensionality reduction and unsupervised clustering approaches.', 'mass cytometry, CyTOF, metal-labeled antibody cytometry, high-dimensional cytometry, single cell protein profiling, HDCyto, time-of-flight mass spec cytometry', 'Mass Cytometry', 'TIS or CEL and AB', NULL, 'D.CYTOF', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 179);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CyTOF Analysis', 'Mass cytometry (CyTOF) is a single-cell proteomic technology that enables simultaneous quantification of dozens of protein markers per cell using heavy metal isotope-conjugated antibodies detected via inductively coupled plasma time-of-flight mass spectrometry. This assay measures the expression of multiple surface and intracellular proteins at the single-cell level, enabling high-dimensional immunophenotyping and functional characterization of complex cell populations without the spectral overlap limitations of conventional fluorescence-based flow cytometry. Data generated from CyTOF analysis is typically processed through normalization and dimensionality reduction pipelines (e.g., viSNE, UMAP, or PCA) to enable visualization and clustering of distinct cell subsets across large, multiplexed datasets.', 'CyTOF analysis, mass cytometry analysis, high-dimensional clustering, viSNE, UMAP mass cytometry, metal-tag cytometry analysis, single cell protein analysis', 'Mass Cytometry Analysis', 'D.CYTOF', NULL, 'A.CYTOF', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 178);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Microfluidic Device Creation', 'Microfluidic device creation fabricates miniature fluidic systems designed to control and analyze small sample volumes. The process involves patterning channels and chambers into materials such as PDMS or glass.\nInput: Design pattern or mold Output: Functional microfluidic device ready for experimental use.', 'microfluidic chip fabrication, organ-on-chip creation, PDMS molding, lab-on-chip, OOC assembly, chip manufacture', 'Device Creation, Microvascular Network Formation', 'CEL', 'AB or TIS', 'OOC', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Device Imaging', 'This assay captures and records metadata associated with device-based imaging procedures, encompassing contextual and technical parameters such as instrument settings, acquisition conditions, device identifiers, and imaging session attributes. It serves as a standardized framework for documenting non-image data elements that accompany imaging acquisitions, ensuring traceability, reproducibility, and data provenance across imaging workflows. The collected metadata supports downstream data integration, quality control, and cross-study comparability by providing structured annotation of the imaging device and acquisition context.', 'microfluidic device imaging, chip imaging, OOC imaging, organ-on-chip microscopy, lab-on-chip visualization', 'Microfluidic Device Imaging', 'OOC', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 37);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Digitally Barcoded Mtb Matrix Analysis', 'Digitally barcoded Mtb matrix analysis processes barcode sequencing data from Mycobacterium tuberculosis infection experiments. It quantifies relative barcode abundance to track bacterial population dynamics.\nInput: Barcode sequencing files Output: Processed abundance matrix showing strain or barcode distribution.', 'MTB barcode analysis, tuberculosis barcode sequencing, Mtb lineage tracking, barcode amplicon sequencing, digitally barcoded bacteria', NULL, 'D.SEQ', NULL, 'A.DBMM', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('DNA Extraction', 'DNA extraction is a fundamental laboratory procedure used to isolate and purify genomic DNA from biological samples for downstream molecular analyses. This assay encompasses the collection of relevant metadata associated with the extraction process, including sample identifiers, source material type, extraction method or kit utilized, instrument parameters, operator information, and quality control metrics such as DNA yield and purity (e.g., A260/A280 ratios). Standardized metadata capture ensures traceability, reproducibility, and integrity of extracted nucleic acid samples across subsequent applications such as sequencing, genotyping, or PCR-based assays.', 'DNA isolation, genomic DNA extraction, gDNA extraction, nucleic acid extraction, DNA purification, QIAamp extraction', 'cDNA Isolation, Extraction and Library Creation', 'BAC or CEL or TIS', NULL, 'DNA', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, 24);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electrochemical Sensor Testing', 'Electrochemical sensor testing measures electrical responses from sensors exposed to defined analytes. The assay characterizes sensitivity, stability, and signal-to-noise performance under experimental conditions.\nInput: Sensor device and test analyte Output: Electrochemical response data or calibration curve.', 'electrochemical sensor testing, biosensor testing, sensor sensitivity, sensor calibration, amperometric testing, voltammetric testing', NULL, 'CHM and SNSR', NULL, 'D.SNSR', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electron Paramagnetic Resonance', 'Electron paramagnetic resonance (EPR) detects unpaired electrons in molecules to study structure and dynamics. The assay measures energy transitions in a magnetic field to characterize molecular environments.\nInput: Prepared chemical or biological sample Output: EPR spectral data representing paramagnetic properties.', 'EPR, ESR, electron spin resonance, paramagnetic spectroscopy, free radical detection, unpaired electron measurement', NULL, 'CHM', NULL, 'D.PRM', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('ELISA', 'This assay employs an enzyme-linked immunosorbent assay (ELISA) methodology to quantitatively detect and measure specific analytes (such as proteins, antibodies, or other biomolecules) in biological samples. The technique utilizes antibody-antigen interactions coupled with enzymatic signal amplification to generate colorimetric or fluorometric readouts proportional to analyte concentration. Sample preparation, incubation conditions, wash steps, and detection reagents are performed according to standardized protocols, with absorbance or fluorescence values measured using a microplate reader and quantified against a calibration curve. Data are linked to associated experimental records to facilitate integrated downstream analysis and result interpretation.', 'enzyme-linked immunosorbent assay, ELISA, sandwich ELISA, plate-based immunoassay, OD measurement, absorbance immunoassay, microplate reader assay', NULL, 'AB or ABP and CEL or TIS', 'CHM', 'D.ELSA', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 26);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fc Receptor Binding Assay', 'This assay evaluates the binding affinity and interaction of test compounds or biological molecules (such as antibodies or Fc-fusion proteins) to Fc receptors (FcRs), which are critical mediators of immune effector functions including antibody-dependent cellular cytotoxicity (ADCC) and phagocytosis. Binding interactions are quantified using established biochemical or biophysical detection methodologies, enabling characterization of Fc-FcR engagement relevant to the functional activity of immunoglobulins or Fc-containing therapeutics. Results are linked to associated experimental datasets, facilitating integrated analysis of structure-activity relationships and supporting the development and optimization of antibody-based therapeutics.', 'Fc receptor binding assay, FcR binding, Fc-gamma receptor assay, FCRB assay, antibody effector function assay, receptor affinity measurement', NULL, 'TIS', NULL, 'D.FCRB', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 27);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('FC Receptor Binding Assay Analysis', 'Fc receptor binding assay analysis processes raw binding data to quantify affinity and functional engagement. It performs curve fitting and normalization to compare binding efficiencies across samples.\nInput: Raw binding assay data Output: Processed binding affinity metrics and comparative plots.', 'FCRB analysis, Fc receptor data analysis, binding curve analysis, affinity quantification, effector function analysis', NULL, 'D.FCRB', NULL, 'A.FCRB', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Field Water Sensor Run', 'A field water sensor run collects environmental data using deployed sensors that measure physical or chemical properties of water. The process records parameters such as temperature, pH, or conductivity.\nInput: Deployed water sensor Output: Environmental dataset containing sensor measurements over time.', 'water sensor run, field sensor deployment, in-situ water sensing, environmental water monitoring, aquatic sensor data', NULL, 'SNSR or LOC', NULL, 'D.SNSR', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Flow Cytometry Analysis', 'Flow cytometry is employed to quantitatively measure cell surface and/or intracellular markers, enabling characterization of cell populations based on fluorescence intensity and light scatter properties. This assay utilizes a flow cytometer to analyze individual cells in suspension, providing multi-parametric data on cell phenotype, viability, activation state, or other biological attributes as defined by the experimental panel. Samples are processed, stained with fluorescently labeled antibodies or dyes, and acquired on the instrument, with downstream analysis performed using dedicated gating strategies to identify and quantify cell subsets of interest.', 'flow cytometry analysis, FACS analysis, gating analysis, cell population analysis, FlowJo analysis, FCS Express, immunophenotyping analysis', NULL, 'D.FLOW', NULL, 'A.FLOW', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 31);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fourier Transform Infrared Spectroscopy', 'Fourier transform infrared spectroscopy (FTIR) measures absorption of infrared light to characterize molecular vibrations. The assay provides information on chemical composition and structural features.\nInput: Chemical or biological sample Output: Infrared spectral data file representing molecular fingerprint.', 'FTIR, infrared spectroscopy, IR spectroscopy, molecular vibration, chemical fingerprint, functional group analysis, mid-IR spectroscopy', NULL, 'TIS or CEL', NULL, 'D.SPC', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gel Permeation Chromatography', 'Gel permeation chromatography (GPC) separates molecules based on size using a porous gel matrix. The assay measures elution times to determine molecular weight distribution.\nInput: Polymer or macromolecular sample Output: Chromatography trace showing molecular size distribution.', 'GPC, size exclusion chromatography, SEC, molecular weight distribution, polymer size separation, chromatography fractionation', NULL, 'CHM', NULL, 'D.GPC', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Genome Alignment', 'This assay involves the computational alignment of sequencing reads to a reference genome, enabling the mapping of raw sequence data to genomic coordinates for downstream variant calling, expression quantification, or structural analysis. Sequencing data files (e.g., FASTQ) are processed using standard bioinformatic alignment tools (such as BWA, STAR, or Bowtie2) to produce aligned output files (e.g., BAM/SAM format), which are subsequently sorted, indexed, and subjected to quality control assessment. This linked-data implementation associates the resulting alignment files directly with corresponding sample metadata and upstream sequencing assay records, facilitating integrated, reproducible genomic analyses within a structured data management framework.', 'read alignment, sequence mapping, reference genome alignment, BWA STAR bowtie, BAM generation, read mapping, NGS alignment', NULL, 'D.SEQ', NULL, 'A.ALN', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 34);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Glycosylation Assay', 'This assay characterizes the glycosylation profile of biological samples by analyzing the composition, structure, and abundance of glycan moieties attached to proteins or other biomolecules. Standard glycosylation analysis workflows typically involve sample preparation steps such as enzymatic release of N-linked glycans (e.g., via PNGase F treatment), followed by labeling or derivatization and separation using chromatographic or electrophoretic techniques (such as HPLC, UHPLC, or capillary electrophoresis) coupled with fluorescence or mass spectrometric detection. Data are linked to associated experimental records to enable integrated downstream analysis, including quantification of individual glycan species, calculation of derived glycosylation traits, and assessment of batch or sample quality. Results support characterization of glycan heterogeneity and may be used to monitor biological processes, product quality attributes, or disease-associated glycosylation changes.', 'glycan analysis, sugar modification analysis, N-glycan profiling, O-glycan analysis, antibody glycosylation, glycoproteomics, carbohydrate characterization', NULL, 'AB', NULL, 'D.GLYN', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 155);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('GPT Assay', 'A GPT (glutamate pyruvate transaminase) assay measures enzyme activity involved in amino acid metabolism. It monitors substrate conversion rates to assess liver function or cellular health.\nInput: Biological or enzyme-containing sample Output: Enzyme activity data or absorbance measurement.', 'GPT assay, glutamate pyruvate transaminase, phage efficiency assay, plaque assay, bacterial transaminase, phage titer', NULL, 'DNA or TIS', NULL, 'D.GPT', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('High Resolution Mass Spectra', 'High-resolution mass spectrometry measures molecular mass with high precision to identify and quantify chemical species. The assay provides detailed profiles of metabolites, peptides, or proteins based on ionized fragments.\nInput: Prepared chemical or biological sample Output: High-resolution mass spectral data file containing mass-to-charge ratios.', 'HRMS, high-resolution mass spectrometry, accurate mass, molecular formula, Orbitrap, QTOF, exact mass measurement', NULL, 'CHM', NULL, 'D.SPC', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('High Resolution Mass Spectra Analysis', 'High-resolution mass spectra analysis processes raw spectral data to identify and quantify molecular components. It performs peak detection, alignment, and annotation to generate compound or peptide identifications.\nInput: Raw mass spectrometry data Output: Processed spectra and annotated molecular feature tables.', 'HRMS analysis, accurate mass analysis, molecular formula confirmation, high-resolution MS data processing', NULL, 'D.SPC', NULL, 'A.SPC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Histopathology', 'Histology assays employ tissue preparation and staining techniques to examine the microscopic structure of biological specimens, enabling detection of morphological changes, cellular organization, and pathological features within tissues. Standard workflows typically involve fixation, embedding, sectioning, and application of stains (such as hematoxylin and eosin or specialized histochemical stains), followed by microscopic imaging and qualitative or quantitative analysis. This dataset represents histological findings that have been linked to associated experimental or clinical records, facilitating integrated interpretation of tissue-level observations alongside complementary study data.', 'histopathology, H&E staining, tissue staining, pathological examination, tissue morphology, hematoxylin eosin, histological analysis', 'Histology', 'TIS', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 145);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Histopathology Analysis', 'Histopathology analysis is a diagnostic and investigative technique that evaluates the microscopic structural and cellular characteristics of tissue samples to identify pathological changes, disease states, or treatment-related effects. Tissue specimens are processed through standard histological workflows including fixation (typically in formalin), paraffin embedding, sectioning, and staining with hematoxylin and eosin (H&E) or other specialized stains, followed by examination under light microscopy. Quantitative or qualitative assessments may include evaluation of tissue architecture, cellular morphology, inflammatory infiltration, necrosis, fibrosis, or other histopathological endpoints by trained pathologists or automated image analysis systems.', 'histopathology analysis, digital pathology, tissue image analysis, H&E analysis, pathological scoring, slide analysis', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 187);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Imaging', 'This imaging assay captures and links visual data to corresponding experimental or sample records, enabling integrated analysis of morphological, spatial, or phenotypic features within a structured data management framework. Image acquisition is performed using standard microscopy or imaging instrumentation, with resulting datasets cross-referenced to associated metadata, experimental conditions, or sample identifiers to facilitate downstream quantitative or qualitative analysis. The linked data architecture supports reproducible retrieval and interpretation of imaging outputs in the context of broader experimental workflows.', 'microscopy, imaging assay, optical imaging, fluorescence imaging, confocal imaging, brightfield imaging, image acquisition', NULL, 'CEL or CHM or TIS', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 36);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Imaging Analysis', 'Imaging analysis processes raw image data to extract measurements or visual patterns. It includes segmentation, quantification, and visualization of spatial features.\nInput: Raw imaging data Output: Processed image metrics and annotated visualizations.', 'image analysis, image processing, image quantification, morphology analysis, segmentation analysis, pixel quantification, computer vision analysis', 'Image Analysis', 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
