INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('ImmunoPeptideomics', 'Immunopeptideomics identifies peptides presented by MHC molecules using mass spectrometry. The assay characterizes antigen presentation and immune recognition across samples.\nInput: Protein or peptide extract Output: Mass spectrometry data profiling peptide-MHC complexes.', 'immunopeptideomics, MHC peptidome, HLA ligandome, antigen presentation profiling, neoantigen, immune peptide identification', NULL, 'TIS or CEL', NULL, 'D.MSP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Intravital Microscopy', 'Intravital microscopy (IVM) is an advanced imaging technique used to visualize and quantify dynamic biological processes in living animals in real time, including cellular behavior, vascular dynamics, immune cell trafficking, and tissue interactions at the microscopic level. The method employs high-resolution optical microscopy platforms — such as confocal, two-photon, or widefield fluorescence microscopes — coupled with appropriate surgical preparation or optical window chambers to provide direct access to tissues of interest (e.g., tumor microenvironment, lymph nodes, liver, or vasculature). Fluorescently labeled cells, proteins, or dyes are introduced into the living subject, and time-lapse image sequences are acquired to track parameters such as cell migration velocity, vessel permeability, leukocyte rolling and adhesion, or reporter gene expression. Quantitative image analysis is subsequently performed using specialized software to extract spatiotemporal metrics from the acquired datasets.', 'intravital imaging, in vivo microscopy, two-photon microscopy, live animal imaging, in vivo fluorescence microscopy', NULL, 'MUS', NULL, 'D.IMG', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 163);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('iPSC Culture and Chrondronoid Formation', 'This assay differentiates induced pluripotent stem cells (iPSCs) into chondronoid structures for cartilage modeling. It combines controlled culture conditions and differentiation factors to generate tissue-like constructs.\nInput: Induced pluripotent stem cells Output: Differentiated chondronoid culture ready for analysis or downstream assays.', 'iPSC culture, chondronoid formation, stem cell 3D culture, cartilage organoid, induced pluripotent stem cell culture', NULL, 'CEL', NULL, 'CEL', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
