INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Long Read Sequencing', 'Long read sequencing produces extended nucleotide sequences that span repetitive or complex genomic regions. The assay uses third-generation platforms to generate highly continuous reads for genome assembly.\nInput: DNA library Output: Long read sequencing file (e.g., FASTQ / D.SEQ) containing extended read data.', 'Oxford Nanopore, PacBio, long-read sequencing, third-generation sequencing, SMRT, nanopore long reads', NULL, 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Luminex', 'A Luminex assay quantifies multiple analytes simultaneously using color-coded microspheres and fluorescence detection. The assay measures cytokines, antibodies, or proteins within a single multiplexed reaction.\nInput: Biological sample Output: Multiplex fluorescence data file representing analyte concentrations.', 'Luminex, xMAP, multiplex bead assay, cytokine panel, bead-based immunoassay, BioPlex, MAGPIX, MFI measurement', NULL, 'TIS or CEL or CEX', NULL, 'D.LMX', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
