INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Analysis', 'This assay employs mass spectrometry-based analytical workflows to detect, identify, and quantify molecular analytes — such as proteins, peptides, metabolites, or small molecules — from processed biological samples, with acquired spectral data computationally linked to corresponding sample records for integrated downstream analysis. Raw mass spectrometry data files are associated with their respective sample identifiers through a data linkage framework, enabling traceability across sample preparation, instrument acquisition, and bioinformatic processing steps. Analytical outputs, including mass-to-charge ratios, retention times, and ion intensities, are systematically organized to support quantitative comparisons, feature annotation, and statistical interpretation within the broader study context.', 'mass spectrometry analysis, MS data processing, protein identification, database search, label-free quantification, spectral analysis', NULL, 'D.SPC', NULL, 'A.SPC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 47);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Proteomics', 'Mass spectrometry proteomics measures protein abundance and post-translational modifications using peptide fragmentation. The assay generates mass spectra representing peptide fingerprints.\nInput: Protein or peptide digest Output: Proteomics mass spectrometry data file.', 'proteomics, LC-MS/MS, shotgun proteomics, bottom-up proteomics, peptide mass fingerprinting, tandem MS proteomics', 'LC - MS/MS (Proteomics), Proteomics', 'TIS or CEL or CEX', NULL, 'D.MSP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry Proteomics Analysis', 'Mass spectrometry proteomics analysis processes raw proteomics data to identify and quantify peptides and proteins. It performs database matching and normalization to generate protein-level abundance profiles.\nInput: Raw proteomics mass spectrometry data Output: Processed protein quantification tables and annotated identifications.', 'proteomics data analysis, MaxQuant, Perseus, protein quantification, proteomics pipeline, peptide identification', 'Proteomics Analysis', 'D.MSP', NULL, 'A.MSP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Migration Assay Analysis', 'This assay evaluates the migratory capacity of cells under defined experimental conditions, quantifying movement through or across a barrier (such as a membrane or wound gap) as a measure of cellular motility and invasive potential. Standard methodologies may include scratch/wound-healing assays or Transwell-based migration chambers, with imaging and automated or manual analysis used to quantify migrated cell numbers or closure rates over time. Data are linked and tracked to enable downstream integration with complementary datasets, supporting multi-parameter analyses of cell behavior in the context of disease modeling, drug screening, or mechanistic studies.', 'cell migration analysis, scratch assay analysis, wound healing analysis, transwell migration analysis, motility quantification, chemotaxis analysis', NULL, 'D.IMG', NULL, 'A.MIGR', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 80);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Model Creation', 'Model creation establishes experimental or computational representations of biological or physical systems. It defines parameters, inputs, and structure for simulation or predictive testing.\nInput: Experimental data or design parameters Output: Constructed model or prototype for validation.', 'model building, computational model generation, machine learning model training, predictive model development, model architecture', NULL, 'A.*', NULL, 'MDL', 'Analyzed', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Model Validation', 'This assay represents a model validation workflow in which experimental data are formally linked to a predictive or computational model to assess its accuracy and reliability. The validation process involves comparing model-predicted outputs against observed experimental measurements, using associated standard operating procedures to ensure consistent sample preparation, instrumentation, and analytical methods. Results are evaluated to confirm that the model meets predefined acceptance criteria for performance, reproducibility, and scientific rigor.', 'model validation, model performance evaluation, model accuracy, cross-validation, model testing, generalization assessment', NULL, 'A.*', NULL, 'MDL', 'Analyzed', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 102);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mouse Challenge', 'A mouse challenge assay introduces a defined treatment, infection, or condition to experimental mice. It assesses physiological, immunological, or pathological responses to controlled exposures.\nInput: Experimental mouse model Output: Treated or exposed mouse sample for downstream analysis.', 'murine challenge, mouse infection model, mouse treatment experiment, in vivo mouse model, mouse exposure', NULL, 'AB or BAC or CHM', NULL, 'MUS', 'Processed', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('MRI', 'Magnetic resonance imaging (MRI) uses magnetic fields and radio waves to generate detailed internal images of tissues and organs. It provides structural and functional information non-invasively.\nInput: Live animal or biological subject Output: MRI image data showing anatomical or functional details.', 'MRI, magnetic resonance imaging, structural MRI, tissue imaging, brain MRI, body MRI, NMR-based imaging', NULL, 'PAV', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('MRI Analysis', 'Magnetic Resonance Imaging (MRI) analysis is a non-invasive imaging technique that utilizes strong magnetic fields and radiofrequency pulses to generate high-resolution, three-dimensional anatomical images of biological tissues and organs. This assay enables quantitative and qualitative assessment of structural morphology, tissue composition, and pathological changes without the use of ionizing radiation. Acquired image data are processed and analyzed using dedicated software to extract measurable parameters such as tissue volume, signal intensity, and structural dimensions, supporting applications in disease characterization, longitudinal monitoring, and preclinical or clinical research studies.', 'MRI image analysis, volumetric MRI analysis, tissue segmentation, radiological image analysis, brain volume analysis', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 176);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mutational Spectra Analysis', 'This assay characterizes the mutational spectrum of biological samples by identifying and quantifying the types, frequencies, and patterns of mutations (such as base substitutions, insertions, and deletions) across a defined genomic region or whole genome. The analysis typically employs next-generation sequencing (NGS) or Sanger sequencing technologies, followed by bioinformatic processing to classify mutations by type (e.g., transitions, transversions) and context, enabling the construction of mutational signatures. Data attached to this assay record provide the primary output of the spectral analysis, which may include mutation frequency tables, signature decomposition results, and graphical representations of the mutational landscape. Results are used to assess mutagenic potential, characterize mutagen exposure, or investigate DNA repair mechanisms in the experimental system under study.', 'mutation signature analysis, SBS signature, COSMIC signature, trinucleotide context, mutational landscape, mutagen characterization', NULL, 'D.SEQ', NULL, 'A.MUSP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 52);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Nuclear Magnetic Resonance Spectroscopy', 'Nuclear magnetic resonance (NMR) spectroscopy measures the magnetic properties of atomic nuclei to determine molecular structures. It provides detailed chemical composition and conformational data.\nInput: Prepared chemical or biological sample Output: NMR spectral data file representing molecular structure information.', 'NMR spectroscopy, proton NMR, 1H NMR, 13C NMR, metabolomics NMR, chemical structure NMR, magnetic resonance spectroscopy', NULL, 'CHM', NULL, 'D.NMR', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Nuclear Magnetic Resonance Spectroscopy Analysis', 'Nuclear Magnetic Resonance (NMR) spectroscopy is employed to characterize the structural and chemical properties of biological samples by detecting the resonance frequencies of atomic nuclei (typically ¹H, ¹³C, or other NMR-active nuclei) in a magnetic field. This technique enables the identification, quantification, and structural elucidation of metabolites, small molecules, or macromolecular components within a sample, providing detailed information on molecular identity and concentration. Data generated from NMR acquisitions are linked to associated experimental records, facilitating integrated analysis and traceability of spectral outputs across the study dataset.', 'NMR analysis, NMR data processing, spectral assignment, metabolite identification NMR, peak assignment, NMR peak analysis', NULL, 'D.NMR', NULL, 'A.NMR', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 91);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Oncopanel', 'An oncopanel assay sequences a targeted set of cancer-associated genes to detect somatic mutations. The process involves library preparation, sequencing, and variant calling for genomic profiling.\nInput: DNA sample Output: Oncopanel sequencing file (e.g., FASTQ / D.SEQ) containing targeted read data.', 'cancer gene panel, targeted oncology sequencing, tumor mutation profiling, cancer genomics, targeted NGS oncology, somatic variant detection', NULL, 'PAT', NULL, 'D.ONC', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Patient Visit', 'This assay captures administrative and clinical metadata associated with patient study visits, serving as a structured data collection framework rather than a biological measurement assay. It records visit-level contextual information such as visit dates, timepoints, subject identifiers, clinical site details, and protocol-relevant annotations that are essential for linking experimental samples and assay results to their proper clinical context. This metadata layer ensures traceability and data integrity across all associated biospecimen collections and downstream analytical assays within the study.', 'clinical visit, study visit, patient encounter, blood draw visit, sample collection visit, longitudinal visit, study timepoint', NULL, 'PAT or NHP', NULL, 'PAV', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, 56);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PDX Cell Line Generation', 'PDX (Patient-Derived Xenograft) cell line generation establishes tumor cell cultures from implanted patient tissue in animal models. The process isolates and expands cells for drug testing or molecular analysis.\nInput: Patient-derived xenograft tissue Output: Cultured PDX cell line suitable for in vitro experimentation.', 'PDX cell line, patient-derived xenograft culture, tumor model cell line, xenograft in vitro model', NULL, 'PAT', NULL, 'CEL', 'Source', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Pendant Drop Tensiometry', 'Pendant drop tensiometry measures surface tension by analyzing the shape of a suspended liquid droplet. The assay determines interfacial properties relevant to material or biological systems.\nInput: Liquid or solution sample Output: Surface tension data or interfacial tension profile.', 'pendant drop tensiometry, surface tension measurement, interfacial tension, droplet shape analysis, tensiometry, surfactant characterization', 'Tensiometry Assay', NULL, NULL, 'D.TNSY', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Permeability Analysis', 'This assay evaluates the permeability characteristics of biological membranes, barriers, or compound formulations, measuring the rate and extent of molecular transport across a defined membrane system. The analysis is conducted using standardized permeability protocols, with experimental data linked to associated datasets for integrated analysis and cross-referencing. Results typically quantify flux, permeability coefficients, or transport rates to assess barrier integrity or compound penetration potential. This linked-data format enables traceability between raw measurements and downstream analytical outputs, supporting reproducibility and data integrity in permeability assessments.', 'barrier permeability analysis, membrane transport analysis, TEER measurement, permeability coefficient, paracellular flux, transwell permeability', NULL, 'D.IMG', NULL, 'A.PERM', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 82);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PET/CT Scan', 'A PET/CT scan combines positron emission tomography with computed tomography to visualize metabolic activity and anatomical structure. It provides functional imaging for research or diagnostic applications.\nInput: Live subject or biological model Output: PET/CT imaging data showing metabolic and anatomical information.', 'PET-CT, positron emission tomography, CT scan, nuclear imaging, FDG-PET, metabolic imaging, hybrid imaging', NULL, 'PAV', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PET/CT Scan Analysis', 'Positron emission tomography combined with computed tomography (PET/CT) is a dual-modality nuclear imaging assay that simultaneously quantifies metabolic activity and anatomical structure by detecting gamma rays emitted from a positron-emitting radiolabeled tracer (typically 18F-FDG) administered to the subject. The PET component provides functional imaging of tracer uptake reflecting cellular glucose metabolism, while the CT component supplies high-resolution structural context for precise anatomical localization and attenuation correction. Standardized uptake values (SUVs) and volumetric parameters are derived from reconstructed images to assess lesion burden, disease activity, or treatment response across tissues of interest.', 'PET-CT analysis, nuclear imaging analysis, FDG uptake analysis, volumetric PET analysis, SUV analysis, metabolic imaging analysis', NULL, 'D.IMG', NULL, 'A.CTSC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 175);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Polymerase Chain Reaction (PCR)', 'PCR amplifies specific DNA sequences to generate measurable quantities for downstream analysis. It cycles through denaturation, annealing, and extension to exponentially replicate target regions.\nInput: DNA sample and primers Output: Amplified DNA product suitable for quantification or sequencing.', 'PCR, qPCR, RT-PCR, gene amplification, primer-based amplification, DNA amplification, quantitative PCR', 'Real-time RT-PCR, PCR: Validation Data', 'RNA or DNA', NULL, 'D.PCR', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Protein Extraction', 'Protein extraction isolates total or specific proteins from cells, tissues, or lysates. It uses buffers and mechanical or chemical disruption to obtain soluble proteins.\nInput: Biological material Output: Purified protein extract for downstream assays.', 'protein isolation, protein purification, cell protein extraction, tissue protein extraction, total protein extraction', NULL, 'TIS or CEL', NULL, 'CEX', 'Processed', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Proximity Extension Assay', 'A proximity extension assay (PEA) quantifies protein abundance using antibody-linked DNA probes. When probes bind to target proteins, they hybridize and are amplified for detection.\nInput: Biological sample Output: Quantitative protein detection data file.', 'Olink assay, proximity extension, proximity ligation, protein biomarker panel, PEA, high-sensitivity proteomics panel', NULL, 'TIS', NULL, 'D.PEX', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('RaDR Image Machine Learning Analysis', 'RaDR image machine learning analysis applies trained computational models to interpret fluorescence or microscopy data from DNA damage assays. It automates quantification of damage signals and cell-level responses.\nInput: Raw RaDR assay imaging data Output: Processed machine learning–derived metrics and classification results.', 'RaDR image ML, machine learning image analysis, automated fluorescence analysis, deep learning microscopy analysis', NULL, 'D.IMG', NULL, 'A.IMG', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
