INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Short Read Sequencing', 'Short read sequencing is a high-throughput next-generation sequencing (NGS) approach used to determine the nucleotide sequence of DNA or RNA fragments, enabling detection of genetic variants, gene expression profiles, or genomic features depending on the library preparation strategy employed. This assay involves fragmentation of input nucleic acids, adapter ligation, and amplification prior to sequencing on short-read platforms (such as Illumina), generating millions of short sequence reads (typically 50–300 bp) in parallel. The resulting raw sequencing data are linked to associated metadata and downstream bioinformatic analyses, including quality control, alignment to a reference genome or transcriptome, and quantification or variant calling as appropriate to the experimental design.', 'Illumina sequencing, short-read NGS, paired-end sequencing, next-generation sequencing, 150bp reads, sequencing run, HiSeq NovaSeq', 'Illumina Sequencing', 'DNA', NULL, 'D.SEQ', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 64);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Simulation Data', 'Simulation data generation uses computational models to recreate experimental conditions or predict outcomes. It provides synthetic datasets for validation, hypothesis testing, or algorithm development.\nInput: Simulation parameters or model inputs Output: Simulated dataset representing modeled system behavior.', 'computational simulation, in silico data, molecular dynamics output, theoretical calculation, quantum chemistry output', NULL, 'CHM', NULL, 'D.SIM', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Clustering Analysis', 'Single cell clustering analysis organizes single-cell expression data into groups with shared transcriptional profiles. It applies dimensional reduction and clustering algorithms to identify cellular subpopulations.\nInput: Single-cell expression matrix Output: Clustered dataset and annotated cell-type identities.', 'scRNA clustering, Seurat clustering, Leiden clustering, cell type annotation, UMAP clustering, dimensionality reduction clustering', 'Single Cell Clustering', 'A.SCXP', NULL, 'A.SCCL', 'Analyzed', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Expression Matrix Analysis', 'Single cell expression matrix analysis processes sequencing data to generate normalized per-cell expression profiles. It integrates quality control, normalization, and dimensionality reduction.\nInput: Single-cell sequencing data Output: Processed expression matrix with cell-level transcript quantifications.', 'single cell expression matrix, gene expression count matrix, feature-barcode matrix, scRNA expression data, single cell count table', 'Single Cell Expression Analysis, Single Nuclear RNASequencing Expression Analysis', 'D.SEQ', NULL, 'A.SCXP', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Slide Imaging', 'Slide imaging digitizes microscope slides to capture high-resolution representations of tissue or cell samples. It enables archiving and computational image analysis.\nInput: Prepared slide Output: Digital slide image file for visualization or analysis.', 'tissue slide imaging, glass slide scanning, digital slide scan, whole slide imaging, WSI scan, histology slide imaging', NULL, 'SLD', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Metabolomics', 'Spatial metabolomics is an analytical approach that maps the distribution and relative abundance of small molecules, lipids, and other metabolites directly within tissue sections or biological samples, preserving spatial context that is lost in conventional bulk metabolomics. This technique typically employs mass spectrometry-based imaging methods such as MALDI-MSI (Matrix-Assisted Laser Desorption/Ionization Mass Spectrometry Imaging), DESI-MSI (Desorption Electrospray Ionization), or related platforms, applied to cryosectioned or fresh-frozen tissue mounted on conductive slides. Sample preparation generally involves careful sectioning, matrix application (for MALDI-based workflows), and instrument acquisition across a defined spatial grid, followed by data processing to generate ion intensity maps correlated with tissue morphology. Downstream analysis integrates mass spectral identification of metabolite features with histological annotation, enabling spatially resolved profiling of metabolic states across distinct tissue regions, cell types, or microenvironments.', 'spatial metabolomics, MALDI metabolite imaging, MSI metabolomics, molecular metabolite mapping, tissue metabolite distribution', NULL, 'TIS', NULL, 'D.MSP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 94);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Proteomics', 'Spatial proteomics is a set of techniques that enables the measurement and localization of proteins within their native tissue or cellular context, providing both quantitative protein abundance data and spatial distribution information at subcellular, cellular, or tissue-wide resolution. These methods typically employ imaging mass spectrometry (e.g., MALDI-MSI or DESI-MSI), multiplexed immunofluorescence or immunohistochemistry, or mass cytometry-based imaging (e.g., IMC or MIBI) to detect and map hundreds to thousands of proteins simultaneously across tissue sections. Sample preparation generally involves fresh-frozen or FFPE tissue sectioning, antigen retrieval, and labeling with isotope- or fluorophore-conjugated antibodies, followed by high-resolution imaging and computational image analysis pipelines for protein quantification and spatial mapping. The resulting data enable characterization of tissue architecture, cell-type composition, protein co-localization, and microenvironmental interactions in biological and clinical specimens.', 'spatial proteomics, tissue protein mapping, multiplexed protein imaging, DSP, IMC proteomics, GeoMx, CyCIF proteomics', NULL, 'TIS', NULL, 'D.MSP', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 69);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Transcriptomics Analysis', 'Spatial transcriptomics analysis processes sequencing and positional data to reconstruct gene expression patterns across tissue space. It integrates imaging and transcriptomic profiles.\nInput: Raw spatial transcriptomics data Output: Processed spatial expression maps and annotated gene matrices.', 'spatial gene expression analysis, Visium analysis, spatially resolved analysis, in situ transcriptomics analysis, tissue transcriptomic mapping', NULL, 'D.SEQ and D.IMG', NULL, 'A.SPTX', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spectroscopy', 'Chemical spectroscopy encompasses a broad suite of analytical techniques that measure the interaction of electromagnetic radiation with matter to determine the composition, structure, and concentration of chemical species within a sample. Methods may include UV-Vis, infrared (IR), Raman, nuclear magnetic resonance (NMR), mass spectrometry-coupled approaches, and atomic spectroscopy, each employing distinct wavelength ranges and instrumentation tailored to specific analyte properties. Sample preparation varies by technique but typically involves dissolution, dilution, or direct presentation of the sample to the instrument, followed by spectral acquisition and quantitative or qualitative analysis using reference standards or spectral libraries. Collectively, these methods provide highly sensitive and selective characterization of molecular identity, purity, and abundance across a wide range of biological and chemical matrices.', 'spectroscopy, optical measurement, wavelength-based analysis, light interaction, spectrophotometry, molecular spectroscopy', 'UV-Vis Spectroscopy', 'CHM', NULL, 'D.SPC', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 25);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spectroscopy Analysis', 'Spectroscopy analysis encompasses the measurement of the interaction between matter and electromagnetic radiation across defined wavelength ranges to characterize the physical, chemical, or molecular properties of biological samples. Raw spectroscopic data are collected using appropriate instrumentation (e.g., UV-Vis, IR, NMR, or mass spectrometry platforms) and subsequently processed to extract quantitative or qualitative information such as absorbance, emission intensity, or spectral signatures. The resulting data support applications including compound identification, concentration determination, and structural characterization within a biomedical research context.', 'spectral analysis, peak analysis, wavelength intensity analysis, absorption emission analysis, spectroscopy data processing', 'UV-Vis Spectroscopy Analysis', 'D.SPC', NULL, 'A.SPC', 'Raw', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, 71);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('SureQuant Analysis', 'SureQuant analysis processes targeted mass spectrometry data to quantify peptides or proteins using internal standards. It calculates absolute or relative abundance values from multiple reaction monitoring (MRM) datasets.\nInput: Raw SureQuant mass spectrometry data Output: Processed quantitative protein measurements and validation metrics.', 'SureQuant, targeted proteomics, heavy-labeled standard peptide, IS-PRM, triggered data-dependent acquisition, internal standard quantification, Orbitrap targeted MS', NULL, 'CEL and CHM', NULL, 'D.MSP', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Imaging', 'Tissue Imaging – Metadata refers to the systematic collection and standardization of descriptive information associated with tissue imaging experiments, capturing key parameters such as sample provenance, preparation protocols, staining or labeling methods, instrument settings, and image acquisition conditions. This metadata framework ensures reproducibility and interoperability of tissue imaging data by documenting contextual details including tissue type, fixation and sectioning procedures, imaging modality (e.g., fluorescence microscopy, brightfield, or multiplexed imaging), and analytical pipeline specifications. Standardized metadata records enable downstream integration, searchability, and quality control of imaging datasets across studies and platforms.', 'tissue microscopy, tissue slide imaging, fluorescence tissue imaging, histological imaging, tissue staining imaging, whole tissue imaging', NULL, 'TIS', NULL, 'D.IMG', 'Processed', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 127);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Sectioning', 'Tissue sectioning is a histological preparation method in which fixed or frozen biological tissue samples are physically cut into thin slices (typically ranging from 1 to 10 micrometers for paraffin-embedded or cryosectioned material) using a microtome or cryostat instrument. This process preserves the spatial architecture and cellular morphology of the tissue, enabling downstream analyses such as immunohistochemistry, immunofluorescence, in situ hybridization, or routine histological staining. Sections are mounted onto glass slides and may undergo additional processing steps such as deparaffinization, antigen retrieval, or permeabilization prior to labeling and imaging-based readout.', 'cryosectioning, microtome sectioning, FFPE sectioning, tissue slicing, cryo-section preparation, histology sectioning', NULL, 'TIS or CEL', NULL, 'SLD', 'Processed', 'Processed', '(insert link here)', NULL, NULL, NULL, NULL, 75);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('TransCompR Cross Species Modeling', 'TransCompR cross-species modeling integrates datasets across species to predict conserved biological relationships. It applies computational models to align gene or protein networks.\nInput: Cross-species expression or phenotype datasets Output: Modeled comparative relationships and prediction outputs.', 'TransCompR, cross-species modeling, comparative computational modeling, species translation model, cross-species computational', NULL, 'A.GEX', NULL, 'MDL', 'Analyzed', 'Analyzed', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tumoroid Formation', 'Tumoroid formation generates 3D tumor-like structures from cancer cells or tissue fragments. The assay models tumor architecture and microenvironment for drug testing or imaging.\nInput: Cancer cells or tumor fragments Output: 3D tumoroid culture ready for analysis.', 'tumoroid, tumor organoid, 3D tumor model, cancer organoid, tumor spheroid, patient-derived organoid, tumor 3D culture', NULL, 'CEL', NULL, 'CEL', 'Source', 'Source', '(insert link here)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Western Blot', 'Western blot is a widely used immunodetection technique that separates proteins by molecular weight via gel electrophoresis, transfers them onto a membrane (typically nitrocellulose or PVDF), and detects specific target proteins using primary and secondary antibodies conjugated to reporter molecules such as horseradish peroxidase or fluorescent dyes. Sample preparation typically involves cell or tissue lysis, protein quantification, and denaturation in SDS-containing loading buffer prior to electrophoresis. Detection is commonly achieved through chemiluminescent or fluorescent imaging systems, with band intensity analyzed using densitometry software to enable semi-quantitative assessment of protein expression levels. This assay is routinely employed to characterize protein abundance, post-translational modifications, and molecular weight confirmation across a wide range of biological samples.', 'western blot, immunoblot, SDS-PAGE, protein gel, WB, blotting, nitrocellulose membrane, protein band detection', NULL, 'CEX or CEL', NULL, 'D.IMG', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 76);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('X-ray Photoelectron Spectroscopy', 'X-ray Photoelectron Spectroscopy (XPS) is a surface-sensitive analytical technique that measures the elemental composition, chemical state, and electronic structure of materials by irradiating a sample surface with X-rays and detecting the kinetic energy and number of photoelectrons emitted from the top 1–10 nm of the material. This assay provides quantitative information on atomic concentrations and chemical bonding environments of elements present at or near the sample surface, enabling characterization of thin films, coatings, nanoparticles, and biomaterial interfaces. Data are typically acquired under ultra-high vacuum conditions using a monochromatic X-ray source, with spectral analysis performed by binding energy peak identification, curve fitting, and comparison to reference databases to determine elemental and chemical speciation.', 'XPS, X-ray photoelectron spectroscopy, surface analysis, elemental composition, binding energy measurement, ESCA, surface chemistry', NULL, 'CHM', NULL, 'D.XRS', 'Source', 'Raw', '(insert link here)', NULL, NULL, NULL, NULL, 157);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Long-Read Sequencing', 'Long read sequencing is a next-generation sequencing approach that generates nucleic acid sequence reads typically exceeding 10 kilobases in length, enabling the detection of complex genomic features such as structural variants, repetitive elements, full-length transcript isoforms, and phased haplotypes that are difficult to resolve with short-read technologies. This methodology employs platforms such as Pacific Biosciences (PacBio) Single Molecule Real-Time (SMRT) sequencing or Oxford Nanopore Technologies (ONT) sequencing, which capture sequence information from single DNA or RNA molecules in real time. Sample preparation generally involves high-molecular-weight nucleic acid extraction, library construction with minimal fragmentation, and size selection to preserve long fragments prior to sequencing. Resulting data are analyzed using specialized bioinformatic pipelines for base calling, alignment to reference genomes, and downstream variant or isoform detection, providing comprehensive insights into genome structure, epigenetic modifications, and transcriptome complexity.', 'long-read sequencing, Oxford Nanopore, PacBio SMRT, third-generation sequencing, long reads, nanopore sequencing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fluorescence-Activated Cell Sorting (FACS)', 'Fluorescence-Activated Cell Sorting (FACS) is a flow cytometry-based technique used to detect, quantify, and physically isolate distinct cell populations based on fluorescent marker expression and light-scattering properties. Cells labeled with fluorescently conjugated antibodies or reporter molecules are passed individually through a laser beam, enabling simultaneous multiparametric analysis of surface and intracellular markers. Sorted cell populations are collected for downstream applications such as genomic, transcriptomic, or functional analyses, with data linked to associated experimental records for integrated analysis.', 'FACS, fluorescence-activated cell sorting, cell sorting, flow-based separation, live cell sorting, electrostatic cell deflection', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Microvascular Network Formation Assay', 'This assay characterizes the formation and morphological properties of microvascular networks, capturing key metadata parameters associated with the self-organization of endothelial or vascular cells into tubular, network-like structures in vitro. Quantitative endpoints typically include measurements of total tube length, branch points, network complexity, mesh area, and vessel segment characteristics, derived through image analysis of cells cultured under pro-angiogenic conditions. The assay serves as a functional readout of angiogenic capacity and vascular morphogenesis, supporting studies of pro- and anti-angiogenic compounds, extracellular matrix interactions, or cell co-culture systems.', 'microvascular network, vascular chip assay, angiogenesis chip, microvascular formation, endothelial network, vascular OOC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 81);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Organ-on-a-Chip Device Fabrication', 'This assay encompasses the fabrication and assembly of a microfluidic Organ-on-a-Chip (OOC) device engineered from cell-embedded layers (CELs) to recapitulate physiologically relevant tissue microenvironments for cancer cell experimentation. The fabrication process involves the integration of living cellular components into microfluidic architectures designed to mimic in vivo organ-level structure and function, enabling controlled perfusion, cell-cell interactions, and spatiotemporal manipulation of the tumor microenvironment. The resulting platform serves as an advanced in vitro model for investigating cancer cell behavior, drug responses, and tumor-stromal interactions under dynamic, physiologically representative conditions.', 'OOC fabrication, organ chip creation, microfluidic organ chip, tissue chip fabrication, body-on-chip, organ-on-chip assembly', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 84);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Culture', 'This assay captures standardized metadata associated with cell culture experimental conditions, documenting key parameters such as cell line identity, passage number, growth media composition, seeding density, incubation conditions (temperature, CO₂ levels, humidity), and treatment details. The recorded metadata serves as essential contextual information to ensure reproducibility and traceability of downstream biological assays performed on cultured cells. This structured documentation supports data integration, quality control, and cross-experiment comparisons within biomedical research workflows.', 'in vitro culture, cell growth, cell propagation, cell maintenance, tissue culture, cell expansion, cell passage', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 85);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Extraction', 'This assay captures and standardizes the metadata associated with cell extraction procedures, documenting key experimental parameters such as cell type, passage number, extraction method, reagents used, and processing conditions applied during the preparation of cellular material for downstream analyses. It serves as a critical data governance step to ensure traceability, reproducibility, and quality control across experiments by recording provenance information for extracted cell samples. The structured metadata collected supports integration with subsequent assays and facilitates cross-study comparisons within biomedical research workflows.', 'cell isolation, cell dissociation, cell extraction, tissue dissociation, enzymatic dissociation, single cell suspension', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 86);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Isolation', 'This assay captures metadata associated with cell isolation procedures, documenting the methodological parameters, reagents, instruments, and conditions used to separate and purify specific cell populations from biological samples. It serves as a standardized record of the isolation workflow, including details such as tissue source, dissociation methods, separation techniques (e.g., density gradient centrifugation, fluorescence- or magnetic-activated cell sorting), and quality metrics applied to ensure cellular integrity and purity. The metadata provides essential provenance and reproducibility information to contextualize downstream analyses performed on the isolated cell populations.', 'cell isolation, cell sorting, cell separation, cell purification, immunomagnetic isolation, negative selection, positive selection', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 87);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bacterial Extraction', 'This assay captures metadata associated with bacterial extraction procedures, documenting the experimental parameters, sample identifiers, reagents, and procedural conditions used during the isolation and extraction of bacterial material from biological or environmental samples. It serves as a standardized record-keeping component that accompanies downstream analytical assays, ensuring traceability and reproducibility by cataloging key variables such as sample source, extraction method, instrument settings, and processing dates. The metadata framework supports data integration, quality control, and cross-study comparisons by providing structured contextual information linked to each bacterial extraction event.', 'bacterial isolation, bacteria extraction, microbial extraction, pathogen isolation, bacterial culture isolation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 88);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Nuclear Magnetic Resonance Spectroscopy', 'Nuclear Magnetic Resonance (NMR) spectroscopy is employed to characterize the structural, chemical, and physical properties of molecules by detecting the resonance frequencies of atomic nuclei (typically ¹H, ¹³C, or other NMR-active nuclei) in a strong magnetic field. This assay provides quantitative and qualitative information on molecular identity, purity, conformation, and dynamics, and may be applied to small molecules, metabolites, proteins, or other biomolecules in solution or solid state. Data generated are linked to associated experimental records, enabling integrated analysis and traceability of spectral outputs, chemical shift assignments, and derived structural parameters within the broader research dataset.', 'NMR spectroscopy, proton NMR, 1H NMR, 13C NMR, metabolomics NMR, chemical structure NMR, magnetic resonance spectroscopy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 89);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Magnetic Resonance Imaging (MRI)', 'Magnetic Resonance Imaging (MRI) is a non-invasive imaging modality that utilizes strong magnetic fields and radiofrequency pulses to generate detailed anatomical and functional images of internal tissues and organs based on the nuclear magnetic resonance properties of hydrogen protons in biological samples. The technique enables visualization and quantification of structural morphology, tissue composition, and physiological parameters without the use of ionizing radiation. Image acquisition and reconstruction are performed using specialized pulse sequences tailored to the biological question of interest, with subsequent analysis involving segmentation, volumetric measurements, or signal intensity quantification using dedicated image analysis software.', 'MRI, magnetic resonance imaging, structural MRI, functional MRI, tissue MRI, brain MRI, NMR imaging, non-invasive imaging', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 90);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('MALDI Mass Spectrometry Imaging (MALDI-MSI)', 'Matrix-Assisted Laser Desorption/Ionization Mass Spectrometry Imaging (MALDI-MSI) is a label-free spatial metabolomics and proteomics technique that enables the simultaneous detection and visualization of the distribution of small molecules, lipids, peptides, and proteins directly within tissue sections. The method involves mounting thin cryosectioned tissue slices onto conductive target plates, applying a UV-absorbing matrix compound that co-crystallizes with analytes, and then rastering a pulsed laser across the tissue surface to generate ions that are analyzed by a mass spectrometer. The resulting data provide spatially resolved mass spectra at each pixel position, allowing generation of ion intensity maps that correlate molecular identities with histological features across the tissue. Downstream analysis typically involves spectral preprocessing, normalization, and multivariate statistical approaches to identify regions of differential molecular composition.', 'MALDI-MSI, MALDI imaging, mass spectrometry imaging, spatial metabolomics, tissue ion imaging, molecular imaging MALDI', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 92);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Spatial Transcriptomics', 'Spatial transcriptomics is a molecular profiling method that measures gene expression across tissue sections while preserving the spatial context of transcriptional activity within the tissue architecture. This assay captures genome-wide or targeted mRNA expression profiles by capturing polyadenylated transcripts at spatially barcoded locations, enabling the mapping of gene expression patterns to specific histological regions. Raw sequencing data are processed through dedicated bioinformatics pipelines to generate spatially resolved expression matrices, which are subsequently analyzed for cell type deconvolution, spatially variable gene identification, and ligand-receptor interaction mapping. The resulting data provide insights into tissue organization, cellular heterogeneity, and microenvironmental interactions within the context of intact tissue morphology.', 'Visium, spatial RNA-seq, spatial gene expression, 10x Visium, spatially resolved transcriptomics, in situ sequencing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 93);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('iPSC Chondrogenic Differentiation and Chondronoid Formation', 'This assay encompasses the culture and maintenance of induced pluripotent stem cells (iPSCs) and their directed differentiation into chondronoids (cartilage-like organoids), capturing associated metadata parameters throughout the process. The protocol involves standard iPSC maintenance under defined culture conditions followed by chondrogenic induction, with metadata recorded to document critical process variables such as passage number, cell viability, differentiation stage, media composition, and culture duration. Resulting chondronoids are characterized for cartilage-specific matrix deposition and cellular organization, providing a reproducible model for studying chondrogenesis and cartilage biology in vitro.', 'iPSC differentiation, chondrogenesis, chondronoid, stem cell cartilage, induced pluripotent stem cell, cartilage organoid, iPSC chondrocyte', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 95);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Culture and Organoid Generation', 'This assay encompasses the standardized procedures for establishing and maintaining cell cultures and generating organoid models, serving as a foundational metadata framework for tracking culture conditions, passage history, and organoid derivation parameters. The methodology involves controlled in vitro propagation of primary cells or cell lines under defined growth conditions, followed by three-dimensional organoid formation using extracellular matrix scaffolds and specialized culture media formulations. Key metadata captured includes cell source and identity, passage number, culture media composition, growth factor supplementation, incubation conditions, and morphological quality assessments to ensure reproducibility and biological fidelity of the model systems.', 'organoid culture, 3D cell culture, organoid formation, spheroid culture, mini-organ culture, 3D tissue model', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 96);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gene Expression Validation Assay', 'This assay measures gene expression levels to validate transcriptomic findings, employing quantitative molecular profiling techniques to confirm and cross-reference expression data against previously generated datasets. Validation workflows typically involve quantitative PCR (qPCR) or complementary hybridization- or sequencing-based methods to verify differential expression patterns identified in primary experiments. Results are linked to associated expression datasets to enable integrated analysis, ensuring reproducibility and consistency of gene expression measurements across experimental conditions.', 'gene expression validation, qPCR validation, RT-PCR confirmation, RNA validation, expression confirmation assay', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 98);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gene Expression Analysis', 'This assay measures genome-wide or targeted gene expression profiles by quantifying RNA transcript levels across experimental samples. Standard workflows for this assay type typically involve RNA extraction and quality assessment, followed by library preparation or probe hybridization and detection using microarray or next-generation sequencing platforms. Raw signal intensities or read counts are subsequently normalized and subjected to differential expression analysis to identify statistically significant changes in transcript abundance between experimental conditions.', 'RNA-seq analysis, differential expression analysis, DESeq2, edgeR, count matrix processing, transcriptomics analysis, STAR kallisto salmon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 99);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Computational Modeling', 'This assay represents a computational modeling workflow in which experimental data are formally linked to mathematical or statistical models, enabling quantitative analysis and interpretation of biological measurements. The approach integrates curated datasets with model parameters to simulate, predict, or characterize biological processes of interest. Results are used to generate mechanistic insights or predictive outputs that extend beyond direct experimental observation.', 'computational model, mathematical model, in silico model, predictive modeling, systems biology model, simulation framework', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Computational Chemistry Simulation Data', 'This assay encompasses computational chemical simulations in which molecular or physicochemical properties are predicted or modeled using in silico methods rather than experimental wet-lab measurements. The simulation-derived data are linked to associated experimental or reference datasets, enabling integration of calculated parameters — such as binding energies, conformational properties, or ADMET descriptors — with empirical assay results for comparative or predictive analyses. Results are generated through computational pipelines and are curated alongside linked biological or chemical activity data to support structure-activity relationship (SAR) modeling and data-driven decision-making.', 'DFT calculation, quantum chemistry, molecular orbital, HOMO LUMO energy, ab initio calculation, computational molecular simulation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 101);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('RaDR Fluorescence Microscopy Image Machine Learning Analysis', 'This assay employs machine learning-based image analysis to quantify and characterize recombination-associated DNA repair (RaDR) events detected through fluorescence microscopy imaging data. Computational algorithms are applied to acquired microscopy images to extract quantitative metrics related to DNA damage response or recombination foci, enabling high-throughput, objective scoring of repair pathway activity. The analysis pipeline processes attached image datasets to identify, classify, and enumerate relevant cellular or molecular features, reducing manual scoring bias and improving reproducibility across experimental conditions.', 'RaDR analysis, machine learning imaging, fluorescence ML analysis, automated image classification, RaDR microscopy, deep learning image analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 103);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Titer Assay Analysis', 'This assay determines the titer of a biological sample — quantifying the concentration or activity of a target agent (such as a virus, antibody, or other biologically active entity) — by performing serial dilutions and measuring the endpoint at which detectable activity is observed. Linked data analysis is employed to integrate and cross-reference measurement outputs, enabling standardized calculation of titer values across samples. Results are expressed as titer units derived from the dilution endpoint or dose-response relationship, providing a quantitative measure of sample potency or concentration.', 'antibody titer assay analysis, bead-based titer analysis, multiplex titer analysis, serology data analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 104);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Multiplex Bead-Based Antibody Titer Panel Assay', 'The Titer Bead Panel Assay is a multiplexed Luminex-based immunoassay that consolidates multiple individual antibody (AB) titer measurements into a unified antibody panel (ABP) for comprehensive humoral immune profiling. Spectrally distinct fluorescent microspheres are each conjugated to a different antigen, allowing simultaneous quantification of antibody titers against multiple targets in a single sample. Serum or plasma is incubated with the bead mixture, and bound antibodies are detected with fluorescently labeled secondary antibodies. A Luminex flow analyzer identifies each bead by its spectral signature and quantifies bound antibody by reporter fluorescence intensity. Results are reported as median fluorescence intensity (MFI) or calculated titers for each antigen in the panel, enabling efficient multiplex characterization of antibody responses across vaccine antigens, pathogen variants, or serological panels.', 'multiplex titer panel, bead-based antibody titer, BAMA, binding antibody multiplex assay, antibody panel titer, multiplex serology', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 105);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Titer Assay', 'A titer assay designed to quantify the concentration or activity level of a specific biological agent (such as a virus, antibody, or other biomolecule) in a given sample, with results linked to associated experimental datasets for integrated analysis. The assay employs serial dilution methodology to determine the highest dilution at which a detectable response or activity is observed, providing a standardized endpoint titer value. Results are systematically recorded and cross-referenced with linked data sources to support downstream comparative analyses and quality assessments.', 'antibody titer assay, serology titer, bead-based titer, endpoint dilution, binding titer measurement, immunoglobulin titer', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 106);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Clustering Analysis', 'Single cell clustering is a computational analysis assay that groups individual cells into distinct clusters based on transcriptomic or multi-omic feature similarity, enabling the identification and characterization of cell populations within heterogeneous samples. This data-linked implementation integrates clustering outputs with associated metadata and upstream single-cell sequencing data (such as scRNA-seq), applying algorithms such as k-means, graph-based (e.g., Louvain/Leiden), or hierarchical clustering to reduce high-dimensional gene expression matrices into interpretable cell groupings. The resulting clusters are typically visualized using dimensionality reduction techniques such as UMAP or t-SNE, and are annotated based on marker gene expression to define cell types, states, or trajectories. The "data-linked" designation indicates that cluster assignments are computationally connected to source datasets, facilitating downstream analyses including differential expression, pathway enrichment, and cross-sample comparisons.', 'scRNA clustering, Seurat clustering, Leiden clustering, cell type annotation, UMAP clustering, dimensionality reduction clustering', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 107);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Sequencing', 'Single-cell sequencing is a high-throughput genomic assay that enables transcriptomic, genomic, or epigenomic profiling at the resolution of individual cells, allowing characterization of cell-type diversity, gene expression heterogeneity, and cellular states within complex biological samples. In this linked-data context, sequencing libraries are prepared from isolated single cells or nuclei — typically via droplet-based or plate-based partitioning methods — followed by next-generation sequencing to generate per-cell molecular profiles. Raw sequencing reads are processed through alignment, demultiplexing, and count-matrix generation pipelines, with the resulting data linked to associated sample metadata, experimental annotations, or complementary datasets to support integrative downstream analyses.', 'scRNA-seq, 10x Genomics, single cell sequencing, droplet-based sequencing, cell barcoding, scATAC-seq, single cell NGS', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 108);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CITE-seq (Cellular Indexing of Transcriptomes and Epitopes by Sequencing)', 'CITE-seq (Cellular Indexing of Transcriptomes and Epitopes by Sequencing) is a multimodal single-cell analysis method that simultaneously measures gene expression (transcriptome) and surface protein levels within individual cells by combining single-cell RNA sequencing with antibody-derived tags (ADTs). This dataset represents linked CITE-seq data, in which transcriptomic and proteomic readouts have been computationally integrated and co-analyzed across matched single-cell libraries. Sample preparation typically involves labeling cells with oligonucleotide-conjugated antibodies prior to droplet-based encapsulation (e.g., 10x Genomics), followed by sequencing of both mRNA and ADT libraries. Downstream analysis pipelines enable dimensionality reduction, clustering, and multimodal integration to provide high-resolution characterization of cell types and states based on combined molecular features.', 'CITE-seq, multimodal single cell sequencing, antibody-derived tags, ADT sequencing, surface protein RNA co-sequencing, protein RNA multiomics', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 109);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single-Nucleus RNA Sequencing (snRNA-seq)', 'Single-nucleus RNA sequencing (snRNA-seq) is employed to quantify genome-wide transcriptional activity at single-cell resolution by isolating and sequencing RNA from individual nuclei derived from tissue samples. This approach generates an expression matrix capturing transcript counts per nucleus, enabling characterization of cell-type composition, gene expression profiles, and transcriptional heterogeneity within complex tissues. Downstream computational analysis of the resulting expression matrix typically includes quality filtering, normalization, dimensionality reduction, and clustering to identify distinct cell populations and differentially expressed genes across experimental conditions.', 'snRNA-seq, single nucleus sequencing, nuclear RNA, frozen tissue sequencing, nucleus isolation, single nucleus transcriptomics', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 110);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Single Cell Expression Analysis', 'This assay quantifies gene expression at single-cell resolution by linking individual cell transcriptomic profiles to associated experimental or clinical data, enabling integrative analysis across multiple data modalities. Single-cell RNA sequencing (scRNA-seq) technology is employed to capture and measure the transcriptional activity of individual cells, generating high-dimensional expression matrices that are subsequently processed through quality control, normalization, and dimensionality reduction pipelines. The linked data framework facilitates downstream analyses such as cell type classification, differential expression, and trajectory inference, supporting the investigation of cellular heterogeneity and gene regulatory dynamics within complex biological samples.', 'scRNA-seq analysis, single cell gene expression analysis, droplet sequencing analysis, 10x Genomics analysis, single cell transcriptomics', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 111);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('PET/CT Scan', 'Positron emission tomography combined with computed tomography (PET-CT) is a hybrid nuclear medicine imaging assay that simultaneously measures functional metabolic activity and anatomical structure within the body. Radioactive tracers (typically 18F-fluorodeoxyglucose, FDG) are administered to the subject, and their differential uptake is detected by the PET component to quantify metabolic or biochemical processes, while the CT component provides high-resolution structural localization. The "Data Linked" designation indicates that resulting imaging data — including standardized uptake values (SUVs), lesion measurements, and anatomical annotations — are integrated and linked to associated clinical or research datasets for downstream analysis. This assay is commonly employed in oncology, neurology, and cardiology research to assess disease burden, treatment response, and physiological function.', 'PET-CT, positron emission tomography, CT scan, nuclear imaging, FDG-PET, metabolic imaging, hybrid imaging', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 112);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electrochemical Sensor Assay', 'This assay employs electrochemical sensing technology to detect and quantify target analytes through measurement of electrochemical signals (e.g., current, voltage, or impedance) generated at a functionalized electrode surface. Samples are prepared and applied to the electrochemical sensor platform, where analyte-electrode interactions produce measurable electrical responses that are recorded and analyzed using dedicated instrumentation and data acquisition software. The resulting electrochemical data are linked to corresponding sample identifiers and metadata to enable downstream analysis, calibration, and quantitative interpretation of analyte concentrations or binding events.', 'electrochemical assay, sensor measurement, amperometric assay, voltammetric assay, impedance assay, biosensor calibration', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 113);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Illumina Next-Generation Sequencing', 'This assay employs Illumina next-generation sequencing (NGS) technology to generate high-throughput sequence data from prepared nucleic acid libraries, enabling detection and quantification of genomic, transcriptomic, or epigenomic features depending on the experimental design. Sequencing libraries are constructed from input samples through standard workflows encompassing nucleic acid extraction, fragmentation, adapter ligation, and amplification, followed by sequencing on an Illumina platform to produce short-read data. The resulting sequencing reads are subsequently processed through bioinformatic pipelines for quality control, alignment to a reference genome or de novo assembly, and downstream analysis to yield quantitative or qualitative molecular readouts linked to the samples of interest.', 'Illumina sequencing, short-read NGS, next-generation sequencing, NovaSeq, HiSeq, paired-end sequencing, sequencing run', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 114);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Library Creation', 'DNA sequencing libraries are constructed from genomic DNA extracted from tissue samples through a series of enzymatic and physical processing steps, including DNA fragmentation, end-repair, adapter ligation, and amplification. This workflow prepares nucleic acid material for downstream high-throughput sequencing by converting extracted DNA into indexed, platform-compatible libraries. The resulting libraries enable comprehensive genomic or transcriptomic interrogation of tissue-derived specimens, facilitating applications such as whole-genome sequencing, targeted sequencing, or RNA-seq depending on the input material and protocol employed.', 'sequencing library creation, library construction, NGS library, adapter ligation, library prep, sequencing input preparation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 115);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Sample Processing', 'This assay captures and standardizes metadata associated with sample processing workflows, documenting critical pre-analytical variables such as sample collection parameters, handling procedures, storage conditions, and processing steps applied to biological specimens prior to downstream analysis. It serves as a structured record-keeping framework to ensure traceability and reproducibility across experimental pipelines by cataloging relevant contextual information — including sample identifiers, collection timestamps, processing protocols, and quality control metrics — that may influence data interpretation. Standardized metadata capture enables harmonization across studies, supports data provenance tracking, and facilitates integration with downstream analytical assays and data repositories.', 'sample preparation, biological sample processing, pre-analytical processing, sample handling, sample prep protocol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 116);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Chemical Synthesis', 'This assay encompasses the chemical synthesis procedures and associated metadata recorded during the preparation of compounds or reagents within a laboratory setting. It documents the synthetic methods, reaction conditions, reagents, and procedural parameters employed to produce target chemical entities. Metadata captured includes synthesis dates, batch identifiers, yield calculations, purity assessments, and relevant physicochemical characterization data to ensure traceability and reproducibility of the synthetic workflow.', 'organic synthesis, compound synthesis, chemical preparation, drug synthesis, synthetic chemistry, reaction product, reagent preparation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 117);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Imaging Analysis', 'This assay involves imaging-based analysis in which visual or fluorescence data are acquired from biological samples and subsequently linked to associated experimental or metadata records for integrated downstream analysis. The methodology encompasses image capture using appropriate imaging instrumentation, followed by computational or manual analysis pipelines to extract quantitative or qualitative measurements from the resulting image data. Linked data integration enables correlation of imaging outputs with complementary assay results, sample annotations, or phenotypic readouts to support multi-parameter biological interpretation.', 'image analysis, image processing, image quantification, morphology analysis, segmentation analysis, pixel quantification, computer vision analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 118);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody Functional Profiling (Systems Serology)', 'Antibody Functional Profiling (AFP) analysis characterizes the functional properties of antibody responses by measuring multiple effector functions and Fc-mediated activities, including antibody-dependent cellular cytotoxicity (ADCC), complement activation, and Fc receptor binding across antibody isotypes and subclasses. This multiplexed systems serology approach typically employs Luminex-based or similar high-throughput bead array platforms to simultaneously quantify a broad panel of antibody features from biological samples such as serum or plasma. Raw data outputs, including median fluorescence intensity (MFI) values and derived functional scores, are processed and normalized to enable downstream multivariate analyses that define polyfunctional antibody profiles associated with immune responses to infection, vaccination, or disease states.', 'systems serology, Fc functional profiling, ADCP ADNP ADCD ADNKA, humoral immune profiling, antibody effector multiplex, Alter lab systems serology', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 119);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('UV-Vis Spectroscopy', 'UV-Visible (UV-Vis) spectroscopy is a quantitative analytical technique that measures the absorbance or transmittance of light by a sample across the ultraviolet and visible wavelength range (typically 190–900 nm), enabling determination of compound concentration, purity, and optical properties based on characteristic absorption profiles. Samples are prepared in appropriate solvents or buffers, loaded into cuvettes or microplate wells, and analyzed using a UV-Vis spectrophotometer, with absorbance values correlated to analyte concentration via Beer-Lambert law or compared against reference spectra for qualitative identification. Data are linked to associated experimental records, facilitating integrated analysis of sample identity, concentration, and physicochemical characterization within the broader study context.', 'UV-Vis spectroscopy, ultraviolet-visible spectroscopy, absorbance measurement, optical density, spectrophotometry, UV absorption', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 120);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Absorption and Emission Spectroscopy', 'This assay characterizes the optical properties of samples by measuring both absorption (UV-Vis spectroscopy) and fluorescence emission spectra, enabling determination of key photophysical parameters such as extinction coefficients, quantum yields, and spectral profiles. Absorption measurements quantify wavelength-dependent light attenuation across the UV-visible range, while emission spectroscopy captures fluorescence or phosphorescence profiles upon defined excitation wavelengths. The linked data format indicates that absorption and emission datasets are paired for the same samples, facilitating direct correlation of ground-state and excited-state optical properties. This approach is commonly applied to characterize fluorophores, chromophores, nanoparticles, or biological molecules, supporting downstream applications such as FRET analysis, probe development, and photophysical modeling.', 'UV-Vis spectroscopy, fluorescence spectroscopy, emission spectroscopy, absorption spectroscopy, optical spectroscopy, spectrophotometry, excitation emission measurement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 121);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cyclic Immunofluorescence (CyCIF)', 'Cyclic Immunofluorescence (CyCIF) is a multiplexed immunofluorescence imaging assay that enables the sequential detection of numerous protein targets within fixed tissue sections or cultured cells through iterative cycles of antibody staining, fluorescence imaging, and signal inactivation. Each cycle involves the application of fluorescently labeled primary or secondary antibodies, followed by wide-field or confocal microscopy image acquisition, and subsequent chemical or photo-bleaching of fluorophores to permit re-staining in successive rounds. The resulting multi-cycle images are computationally registered and integrated to generate high-dimensional, spatially resolved protein expression maps at single-cell resolution. This approach enables comprehensive characterization of cellular phenotypes, spatial organization, and tumor microenvironment composition within complex biological specimens.', 'CyCIF, cyclic immunofluorescence, t-CyCIF, iterative staining imaging, multiplexed fluorescence tissue, sequential antibody imaging', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 122);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Lysate Preparation', 'This assay involves the preparation of cell lysate samples through a standardized workflow encompassing cell culture maintenance and subsequent chemical or mechanical lysis of harvested cells. Cells are cultured under defined conditions following an established cell culture protocol, then subjected to a treatment and lysis procedure designed to disrupt cellular membranes and release intracellular contents into a soluble fraction. The resulting lysates serve as biological starting material for downstream biochemical or molecular analyses, such as protein quantification, Western blotting, or other cell-based endpoint measurements.', 'cell lysis preparation, lysate preparation, RIPA lysis, protein extraction cells, bead homogenization, freeze-thaw lysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 123);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tissue Lysis', 'Tissue lysis is a sample preparation procedure in which biological tissue is mechanically and/or chemically disrupted to release intracellular contents, including proteins, nucleic acids, and metabolites, into a homogeneous lysate suitable for downstream analytical assays. The process typically involves homogenization using bead-based disruption, rotor-stator homogenizers, or freeze-thaw cycling in combination with lysis buffers optimized for the target analyte class (e.g., RIPA buffer for protein extraction, guanidinium-based buffers for RNA isolation). Key metadata parameters recorded during this procedure include tissue mass, lysis buffer composition and volume, homogenization instrument settings, temperature conditions, and centrifugation parameters used to clarify the lysate. Standardized documentation of these metadata ensures reproducibility across experiments and enables normalization of downstream quantitative measurements to input tissue amount.', 'tissue homogenization, tissue disruption, tissue lysis, bead beating, mechanical tissue lysis, tissue protein extraction', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 124);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Protein Extraction', 'Protein extraction from tissue samples is a preparative procedure designed to isolate and solubilize the total protein content from biological tissues for downstream quantitative or qualitative analyses. The process typically involves mechanical disruption (e.g., homogenization) and/or chemical lysis of tissue using detergent-based buffers (such as RIPA or similar lysis buffers), followed by centrifugation to remove cellular debris and insoluble material. The resulting protein-containing supernatant can subsequently be used in applications such as Western blotting, ELISA, mass spectrometry, or protein quantification assays to characterize protein expression, abundance, or activity within the tissue of interest.', 'protein isolation, protein purification, cell protein extraction, tissue protein extraction, total protein extraction', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 125);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Sensor Creation', 'This assay captures and records the foundational metadata associated with the creation and configuration of experimental sensors, including parameters such as sensor type, identifier, calibration details, and operational specifications. The process involves systematic documentation of sensor attributes to ensure traceability, reproducibility, and standardization across experimental workflows. Metadata collection follows defined protocols to facilitate downstream data integration, quality control, and accurate interpretation of sensor-derived measurements.', 'biosensor fabrication, sensor development, electrochemical sensor construction, device fabrication, sensor manufacturing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 126);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Device Creation', 'This entry represents a metadata record associated with the creation and configuration of a laboratory device or instrument within a data management system, capturing administrative and descriptive attributes such as device identifiers, specifications, and operational parameters. Rather than measuring a specific biological analyte or employing a defined experimental method, this record serves as a foundational reference object that links downstream assays and experimental data to the physical or virtual instrument used in their execution. The metadata captured may include device name, type, version, calibration status, and associated protocols, ensuring traceability and reproducibility across experimental workflows.', 'microfluidic device fabrication, chip fabrication, PDMS chip, lab-on-chip creation, OOC device, organ-on-chip assembly', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 128);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('High Resolution Mass Spectrometry (HRMS)', 'High-resolution mass spectrometry (HRMS) assay that provides accurate mass measurements and molecular formula determination for chemical compounds, enabling precise identification and structural characterization of analytes. This assay acquires full-scan or targeted mass spectral data with high mass accuracy (typically <5 ppm), capturing isotope patterns, fragmentation profiles, and molecular ion information that are linked to associated compound records or experimental datasets. The methodology supports dereplication, unknown compound identification, and confirmation of chemical structures through exact mass matching against theoretical or database values.', 'HRMS, high-resolution mass spectrometry, accurate mass determination, Orbitrap, QTOF, elemental composition, molecular formula confirmation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 129);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mass Spectrometry', 'This assay employs mass spectrometry-based proteomics to identify and quantify proteins present in biological samples, leveraging tandem mass spectrometry (MS/MS) workflows that typically include sample digestion, peptide separation by liquid chromatography, and downstream spectral analysis. Raw data files are linked to external repositories or supplementary resources, enabling reproducible access to the underlying spectral and quantitative datasets. Protein identification and quantification are achieved through database searching of acquired spectra against reference proteomes, providing comprehensive coverage of the sample proteome.', 'LC-MS, mass spectrometry, MS/MS, tandem mass spec, mass-to-charge measurement, ion detection, mass spec analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 130);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Luminex Multiplex Immunoassay', 'Luminex is a multiplexed bead-based immunoassay platform that enables simultaneous quantitative detection of multiple analytes (such as cytokines, chemokines, antibodies, or other proteins) within a single biological sample. The technology utilizes fluorescently color-coded microspheres conjugated with capture antibodies or antigens, with analyte detection achieved via a secondary reporter fluorophore measured on a flow-based laser detection instrument. Sample preparation typically involves centrifugation to obtain serum or plasma, followed by incubation with the bead panel, washing steps, and signal acquisition using dedicated Luminex instrumentation (e.g., MAGPIX or FLEXMAP 3D). Data analysis is performed using standard curve interpolation software to derive analyte concentrations, with results linked to associated study datasets for downstream statistical and biological interpretation.', 'Luminex multiplex, bead-based multiplex immunoassay, cytokine multiplex, xMAP immunoassay, MAGPIX assay, BioPlex assay', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 131);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Mouse Challenge Experiment', 'This assay captures metadata associated with mouse challenge experiments, documenting experimental parameters and study design variables used to contextualize in vivo infection or immunization studies in murine models. Recorded metadata typically includes animal identifiers, strain, sex, age, weight, challenge route, inoculum dose, pathogen or antigen details, and study timeline information. This structured metadata framework ensures traceability and reproducibility of mouse challenge studies by providing essential experimental context required for downstream data interpretation and cross-study comparisons.', 'mouse challenge experiment, murine infection, in vivo mouse challenge, experimental mouse model, mouse treatment protocol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 132);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Pathogen Challenge and Antibody Depletion', 'This assay captures metadata associated with pathogen challenge experiments conducted in conjunction with antibody depletion procedures, documenting key experimental parameters such as challenge agent identity, dose, route of administration, timepoints, and antibody depletion regimens employed. It serves as a structured record-keeping framework to annotate study design variables, animal cohort assignments, and treatment conditions that contextualize downstream immunological and virological outcome measurements. The metadata schema ensures standardized tracking of experimental variables across studies, facilitating data integration, reproducibility, and cross-study comparisons in the context of vaccine efficacy and immune correlates research.', 'pathogen challenge antibody depletion, infection and antibody removal, challenge and passive transfer, depletion infection model', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 133);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Viability Assay', 'Cell viability assays quantify the proportion of live, dead, or metabolically active cells within a population to assess cytotoxicity, proliferation, or treatment response. These assays commonly employ colorimetric, fluorometric, or luminometric methods — such as MTT/MTS reduction, ATP-based luminescence (e.g., CellTiter-Glo), or membrane integrity dyes — to generate a measurable signal proportional to the number of viable cells. Results are typically normalized to untreated controls and expressed as percent viability or relative survival, enabling quantitative comparison across experimental conditions or compound concentrations.', 'cell viability assay, MTS assay, MTT assay, WST-1, CellTiter-Glo, live/dead staining, cytotoxicity measurement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 134);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Bacterial Survivability Restriction Assay', 'This assay evaluates the ability of bacterial populations to survive under defined restrictive conditions, quantifying survivability metrics through linked experimental data to assess bacterial viability and growth inhibition. The methodology incorporates controlled exposure of bacterial cultures to restrictive agents or environmental stressors, with outcomes measured via standardized enumeration or optical density-based approaches to determine survival rates relative to untreated controls. Results are linked to associated datasets enabling comparative analysis of bacterial strain susceptibility and resistance profiles under the tested conditions.', 'BSRA, bacterial killing assay, antimicrobial assay, bacterial viability assay, growth inhibition, luminescent bacteria assay, infection restriction', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 135);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Real-time RT-PCR', 'Real-time reverse transcription polymerase chain reaction (RT-PCR) assay designed to quantitatively detect and measure RNA targets, enabling gene expression analysis or pathogen detection from biological samples. This method involves reverse transcription of RNA into complementary DNA (cDNA) followed by real-time fluorescent monitoring of PCR amplification, allowing quantification of specific nucleic acid sequences. Results are linked to associated experimental data records, facilitating integrated analysis of expression profiles or detection outcomes across study samples.', 'qRT-PCR, quantitative RT-PCR, real-time PCR, gene expression qPCR, mRNA quantification, TaqMan assay, SYBR Green PCR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 136);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Polymerase Chain Reaction (PCR)', 'Polymerase Chain Reaction (PCR) is a molecular biology technique used to amplify specific DNA or RNA sequences from a target sample through repeated cycles of denaturation, primer annealing, and enzymatic extension, enabling sensitive detection and quantification of target nucleic acids. The assay employs thermocycler instrumentation and sequence-specific oligonucleotide primers to exponentially replicate defined genomic regions, facilitating applications such as pathogen detection, genotyping, gene expression analysis, and mutation identification. Sample preparation typically involves nucleic acid extraction and purification prior to amplification, and results are analyzed via gel electrophoresis, fluorescent detection, or sequencing depending on the assay format (conventional, quantitative, or digital PCR).', 'PCR, qPCR, RT-PCR, gene amplification, primer-based amplification, DNA amplification, quantitative PCR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 137);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('CometChip Assay', 'The Comet Chip assay is a high-throughput microarray-based adaptation of the single-cell gel electrophoresis (comet) assay used to quantify DNA strand breaks and damage at the individual cell level. Cells are arrayed onto a micropatterned chip containing thousands of microwells, enabling simultaneous analysis of hundreds to thousands of individual cells under standardized electrophoresis conditions. Following electrophoresis, fluorescently stained DNA migration patterns ("comets") are imaged and analyzed to quantify parameters such as percent tail DNA, tail moment, and tail length, which reflect the extent of genomic damage. This linked dataset format associates raw or processed comet image data with corresponding sample metadata, experimental conditions, and analytical outputs to facilitate systematic comparison across samples and experimental groups.', 'CometChip, comet assay, DNA strand break assay, genotoxicity assay, high-throughput comet, alkaline electrophoresis DNA damage', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 138);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Necropsy', 'Necropsy metadata captures systematic morphological and physiological observations recorded during post-mortem examination of study subjects, including gross pathological findings, organ weights, and macroscopic lesion identification. This assay documents standardized descriptive parameters collected at the time of necropsy, such as animal identifiers, sacrifice conditions, body weight at termination, and qualitative tissue observations prior to histopathological processing. The recorded metadata serves as a critical contextual framework linking in-life study data to downstream pathological analyses, ensuring traceability and reproducibility across preclinical or toxicological study endpoints.', 'animal necropsy, post-mortem examination, animal autopsy, dissection, pathological dissection, organ harvest post-mortem', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 139);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Digitally barcoded Mycobacterium tuberculosis barcode amplicon sequencing (barcode-by-sample count matrix)', 'This assay quantifies the relative abundance and dynamics of Mycobacterium tuberculosis strains that have been labeled with unique digital DNA barcodes, producing a barcode-by-sample count matrix for assessment of strain fitness, dissemination, or treatment response. It employs targeted PCR amplification of barcode loci from extracted bacterial genomic DNA followed by next-generation sequencing and read-mapping to a reference barcode library. Sample preparation and SOP steps include DNA extraction and library amplification/cleanup on standard molecular biology equipment (thermocycler, fluorometer/fragment analyzer) and computational demultiplexing, mapping, and normalization to generate the final barcode count matrix for downstream statistical analysis.', 'MTB barcode sequencing, tuberculosis barcode amplicon, barcode count matrix, Mtb population dynamics, barcoded strain tracking', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 140);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Immunohistochemistry', 'Immunohistochemistry (IHC) is a histological technique that detects and localizes specific proteins or antigens within tissue sections through the use of labeled antibodies, enabling assessment of protein expression, distribution, and abundance in a spatially resolved context. Tissue samples are typically fixed, embedded, sectioned, and subjected to antigen retrieval prior to incubation with primary and secondary antibodies conjugated to detectable reporters such as enzymatic or fluorescent labels. Image acquisition and analysis are performed to quantify staining intensity, cellular localization, and expression patterns across tissue regions. This assay links immunostaining data to associated experimental or clinical metadata, supporting integrative analyses of biomarker expression in the context of disease state, treatment, or other study variables.', 'IHC, immunostaining, antibody tissue staining, protein localization tissue, chromogenic IHC, DAB staining, fluorescent IHC', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 141);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('X-ray Crystallography', 'Single-crystal X-ray crystallography is a structural determination technique that measures the diffraction pattern of X-rays passing through a crystalline sample to elucidate the three-dimensional atomic and molecular structure of a compound. In this assay, a suitable single crystal is mounted and exposed to an X-ray beam, and the resulting diffraction data are collected, indexed, and refined to yield precise bond lengths, bond angles, torsion angles, and absolute configuration. The method provides unambiguous structural characterization of small molecules or macromolecules, with linked data indicating that crystallographic datasets (e.g., structure factors, CIF files) are deposited or referenced in an associated database or repository for validation and reproducibility.', 'X-ray crystallography, XRD, crystal structure determination, single crystal diffraction, Bragg diffraction, 3D molecular structure, small molecule crystallography', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 142);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Alanine Aminotransferase (ALT/GPT) Activity Assay', 'The GPT assay is a mutational analysis method used to detect and characterize mutations within the *gpt* (guanine phosphoribosyltransferase) transgene, serving as a reporter system for quantifying in vivo mutagenesis. Genomic DNA is extracted from tissue samples of transgenic animals carrying the *gpt* delta reporter construct. The transgene is rescued using lambda phage packaging, and mutations are detected by selecting for 6-thioguanine-resistant colonies (indicating loss-of-function mutations in gpt) on selective media. Mutant frequency is calculated as the ratio of 6-TG resistant colonies to total rescued colonies. Individual mutant clones can be sequenced to characterize the mutation spectrum (point mutations, deletions, insertions). This assay provides a sensitive readout of genotoxic exposure and mutagenic potential across multiple tissues. Data attached.', 'ALT assay, GPT assay, alanine aminotransferase, liver enzyme assay, hepatotoxicity marker, transaminase activity, liver function test', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 143);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Tensiometry Assay', 'Tensiometry is a physicochemical assay used to measure the surface tension of liquid samples, enabling the detection and quantification of surface-active compounds (surfactants) based on their ability to reduce interfacial tension at liquid-air or liquid-liquid boundaries. The method typically employs instruments such as a du Noüy ring tensiometer or Wilhelmy plate apparatus, which record the force required to detach a probe from the liquid surface, providing a direct measure of surface tension in units of mN/m. In a chemical validation context, this assay is used to confirm the surface-active properties of test compounds, assess concentration-dependent behavior (e.g., critical micelle concentration determination), and validate the physicochemical integrity of formulations. Results are analyzed by comparing measured surface tension values against reference standards or established thresholds to confirm the presence and potency of surface-active chemical entities.', 'tensiometry assay, surface tension assay, interfacial tension measurement, droplet tensiometry, surface energy measurement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 146);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Field Water Quality Sensor Measurement', 'This assay monitors and records real-time physicochemical parameters of water samples or environmental water bodies using field-deployed sensor instrumentation. Measured parameters typically include but are not limited to temperature, pH, dissolved oxygen, conductivity, turbidity, and/or salinity, depending on the sensor array deployed. Data are collected in situ using portable or submersible multi-parameter probes, with readings logged at defined intervals according to field sampling protocols. Results support environmental water quality assessment, hydrological monitoring, or field-based research applications.', 'water quality sensor, field water measurement, in-situ water monitoring, drinking water sensor measurement, field water chemistry', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 147);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Convolutional Neural Network (CNN) Assay', 'This assay employs a Convolutional Neural Network (CNN) computational framework to analyze and classify biomedical imaging or high-dimensional data through deep learning-based pattern recognition. The methodology leverages linked datasets as training and/or validation inputs, enabling the CNN architecture to extract hierarchical features and generate predictive outputs such as phenotypic classifications, morphological scores, or biomarker quantification. Data preprocessing, model training parameters, and validation metrics are defined according to associated analytical pipelines, with outputs typically reported as class probabilities, regression values, or segmentation maps derived from the learned feature representations.', 'CNN assay, deep learning assay, image classification model, neural network analysis, convolutional network, computer vision analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 148);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Complement Deposition (ADCD) Assay', 'Antibody-dependent complement deposition (ADCD) is a functional humoral immune assay that quantifies the ability of antigen-specific antibodies to activate the complement cascade and deposit complement components (typically C3) onto antigen-coated beads or target surfaces. In this assay, immune complexes formed between sample antibodies and antigen are incubated with a complement source, and subsequent complement deposition is measured by flow cytometry using fluorescently labeled anti-C3 detection reagents. Sample preparation involves heat inactivation of endogenous complement in test sera, followed by incubation with antigen-coupled beads and guinea pig or human complement. Data are acquired on a flow cytometer and reported as median fluorescence intensity (MFI), reflecting the magnitude of complement fixation activity in the sample.', 'ADCD assay, complement deposition assay, C3 deposition, complement fixation, opsonization complement assay', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 149);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Neutrophil Phagocytosis (ADNP)', 'Antibody-Dependent Neutrophil Phagocytosis (ADNP) is a functional immunoassay that measures the capacity of antigen-specific antibodies to opsonize targets and drive their uptake by primary human neutrophils via Fc receptor engagement. Antigen-coated fluorescent beads or immune complexes are incubated with serum or plasma, then combined with freshly isolated neutrophils. After incubation, phagocytic activity is quantified by flow cytometry, measuring the percentage of neutrophils that have internalized fluorescent beads and/or the fluorescence intensity per cell. Results are reported as a phagocytic score (percent positive cells × mean fluorescence intensity) providing a functional measure of antibody-dependent neutrophil phagocytosis (ADNP) activity mediated by innate immune effector cells. ADNP is a key component of systems serology profiling, reflecting the ability of antibodies to recruit neutrophil-mediated clearance mechanisms. Data linked to corresponding experimental metadata for integrated analysis.', 'ADNP, neutrophil phagocytosis assay, granulocyte phagocytosis, antibody-mediated neutrophil uptake', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 150);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Cellular Phagocytosis (ADCP)', 'Antibody-dependent cellular phagocytosis (ADCP) is a functional humoral immune assay that quantifies the capacity of antigen-specific antibodies to facilitate phagocytic uptake of antibody-opsonized targets by effector cells, typically monocytes or neutrophils. The assay generally employs fluorescently labeled antigen-coupled beads or target cells incubated with heat-inactivated serum or plasma samples, followed by co-culture with phagocytic effector cells, with uptake measured by flow cytometry. A phagocytosis score is calculated based on the percentage of phagocyte-positive cells and the fluorescence intensity of internalized signal, providing a quantitative readout of Fc-mediated effector function. This assay is commonly used in vaccine immunogenicity studies and therapeutic antibody evaluations to assess non-neutralizing antibody effector functions that may contribute to protective immunity.', 'ADCP, phagocytosis assay, opsonophagocytosis, THP-1 phagocytosis, monocyte phagocytosis, bead uptake, antibody-mediated phagocytosis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 151);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent NK Cell Activation Assay', 'This assay measures antibody-dependent NK cell activation by quantifying the functional response of natural killer (NK) cells stimulated in the presence of specific antibodies bound to target antigens. The assay evaluates NK cell activation markers (such as CD107a degranulation and/or intracellular cytokine production, e.g., IFN-γ) using flow cytometry-based detection, reflecting the ability of antibodies to engage NK cell Fc receptors (primarily FcγRIII/CD16) and drive effector responses. Sample preparation typically involves co-culturing peripheral blood mononuclear cells (PBMCs) or purified NK cells with antibody-coated target cells, followed by staining with fluorochrome-conjugated antibodies and acquisition on a multi-parameter flow cytometer. Data are analyzed to determine the frequency or magnitude of activated NK cell populations, providing a functional readout of antibody-mediated innate immune engagement relevant to vaccine and therapeutic antibody research.', 'ADNKA assay, NK cell activation assay, natural killer cell assay, ADCC assay, antibody-dependent cytotoxicity assay', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 152);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Functional Profiling (ADFP)', 'Antibody Dependent Functional Profiling (ADFP) is a multiplexed assay that characterizes the functional capacity of antigen-specific antibodies by simultaneously measuring multiple Fc-mediated effector functions, including antibody-dependent cellular cytotoxicity (ADCC), antibody-dependent cellular phagocytosis (ADCP), antibody-dependent neutrophil phagocytosis (ADNP), and complement deposition (ADCD). The assay employs Luminex-based bead arrays coupled with flow cytometry to profile antibody-mediated recruitment and activation of innate immune effector cells, utilizing fluorescently labeled antigen-coupled microspheres incubated with serum samples and relevant effector cells or complement sources. Data outputs include median fluorescence intensity (MFI) and phagocytic or cytotoxic scores derived from multiparameter flow cytometric analysis, enabling high-throughput, systems-level characterization of humoral immune responses across large sample cohorts.', 'ADFP, antibody-dependent functional profiling, systems serology, Fc effector function, immune functional fingerprint', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 153);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Antibody-Dependent Neutrophil Phagocytosis Analysis', 'This assay quantifies the ability of antibodies to mediate neutrophil-driven phagocytosis of target antigens (such as viral particles, bacteria, or opsonized beads), serving as a functional measure of antibody-mediated innate immune effector activity. Primary human neutrophils or neutrophil-like cell lines are incubated with fluorescently labeled antigen-antibody complexes, and phagocytic uptake is assessed by flow cytometry to determine the proportion of neutrophils that have internalized the target. A phagocytosis score is calculated based on the frequency of phagocyte-positive cells and the median fluorescence intensity of internalized signal, enabling quantitative comparison across samples. This assay is commonly employed in vaccine immunogenicity studies and correlates of protection analyses to evaluate non-neutralizing antibody functions linked to protective immunity.', 'ADNP analysis, neutrophil phagocytosis analysis, granulocyte assay analysis, innate effector analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 154);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Gel Permeation Chromatography (GPC)', 'Gel Permeation Chromatography (GPC) is a size-exclusion chromatographic technique used to determine the molecular weight distribution, average molecular weights (Mn, Mw), and dispersity (Đ) of polymer samples by separating molecules according to their hydrodynamic volume in solution. In this assay, samples are dissolved in an appropriate solvent, filtered, and injected onto a series of porous columns calibrated against molecular weight standards (e.g., polystyrene or polymethyl methacrylate), with detection typically performed using refractive index (RI), ultraviolet (UV), or light scattering detectors. The resulting chromatographic data are processed using dedicated software to generate molecular weight distribution curves and associated statistical parameters, with results linked to corresponding sample records for traceability and downstream data analysis.', 'GPC, SEC, size exclusion chromatography, molecular weight distribution, polymer characterization, hydrodynamic volume separation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 156);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Electron Paramagnetic Resonance (EPR) Spectroscopy', 'Electron Paramagnetic Resonance (EPR) spectroscopy is employed to detect and characterize paramagnetic species, including free radicals, radical intermediates, and transition metal complexes, within biological or chemical samples. This technique measures the absorption of microwave radiation by unpaired electrons in the presence of an external magnetic field, providing information on the identity, concentration, and electronic environment of paramagnetic centers. Samples are prepared under controlled conditions to preserve radical species and analyzed using an EPR spectrometer, with spectral data processed to extract parameters such as g-values, hyperfine coupling constants, and spin concentration. The resulting data are linked to associated experimental records, enabling integration with broader study datasets for comprehensive interpretation of oxidative stress, metalloprotein activity, or reaction mechanism studies.', 'EPR spectroscopy, ESR spectroscopy, electron paramagnetic resonance, spin label, radical detection, paramagnetic characterization', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 158);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Hierarchical Clustering', 'Hierarchical clustering is an unsupervised machine learning method that organizes data points into nested, hierarchical groupings based on pairwise distance or similarity metrics (e.g., Euclidean or Manhattan distance), without requiring a predetermined number of clusters. The algorithm proceeds either agglomeratively (bottom-up, iteratively merging the closest clusters) or divisively (top-down, recursively splitting the most heterogeneous cluster), with inter-cluster distances defined by a chosen linkage criterion such as single, complete, average, or Ward\'s minimum variance linkage. Results are visualized as a dendrogram, from which discrete clusters are derived by applying a threshold cut at an appropriate hierarchical level. This approach is widely employed in biomedical and bioinformatics contexts — including gene expression profiling, multi-omics data integration, and patient stratification — to reveal inherent structure and co-expression or co-occurrence patterns within complex, high-dimensional datasets.', 'hierarchical clustering, dendrogram, agglomerative clustering, Ward linkage, cluster analysis, unsupervised clustering', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 159);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Area Under the Curve (AUC)', 'Area Under the Curve (AUC) is a mathematical integration method used to summarize the cumulative magnitude of a measured response over time or across a range of conditions. In biological research, AUC is applied to diverse data types: antibody binding curves, dose-response relationships, viral load kinetics, cytokine secretion time courses, and analyte abundance profiles. The calculation integrates the area between the response curve and the baseline (typically via the trapezoidal rule), yielding a single scalar value that captures both the intensity and duration of the measured response. For example, in pharmacokinetics, AUC quantifies total drug exposure over time, while in serology, it summarizes total antibody reactivity across antigen concentrations. AUC values enable standardized comparison across experimental groups, time points, or treatment conditions. Results are reported in units of [response × independent variable] (e.g., OD × concentration, copies/mL × days) and are commonly used as summary endpoints in vaccine immunogenicity, therapeutic efficacy, and biomarker studies.', 'AUC, area under the curve, pharmacokinetics AUC, dose-response AUC, ROC-AUC, bioavailability, exposure calculation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 160);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Environmental sample collection', 'This assay describes the systematic collection of samples from non-biological environmental sources, such as water samples obtained from drinking water distribution systems or other geographic locations. The process establishes a hierarchical relationship between a parent sample type representing a geographic location (LOC) and a child sample type representing the collected environmental material (e.g., WTR for water), enabling spatial tracking and traceability of collected specimens. No biological extraction or analytical instrumentation is applied at this stage', 'environmental sampling, field collection, water sampling, environmental monitoring, soil sampling, field sample collection', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 161);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Solid Phase Extraction (SPE)', 'Solid-phase extraction (SPE) is a sample preparation technique used to isolate, purify, and concentrate target analytes or remove unwanted matrix components from complex liquid samples prior to downstream chromatographic analysis (LC/GC–MS). The method operates by passing a sample through a sorbent bed—formatted as cartridges, disks, or multi-well plates—where selective retention is achieved through controlled interactions between the analytes and the sorbent material, followed by sequential wash and elution steps to recover purified compounds. SPE is widely applied across environmental monitoring (water and soil contaminants), pharmaceutical and bioanalytical workflows (drugs and metabolites from plasma or urine), clinical and forensic toxicology, and food-safety testing (mycotoxins, pesticide residues, and veterinary drug residues), with microextraction variants available for reduced solvent consumption and higher-throughput formats.', 'solid phase extraction, SPE cleanup, sample cleanup, cartridge extraction, analyte enrichment, sample purification SPE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 162);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Cell Imaging', 'This assay employs cell imaging methodologies to capture and analyze visual data from biological samples at the cellular level, with experimental measurements linked to associated datasets for integrated analysis. Imaging data is acquired using microscopy-based instrumentation, enabling quantification of cellular morphology, spatial distribution, fluorescence signals, or other phenotypic parameters depending on the experimental context. The linked data structure facilitates cross-referencing of image-derived metrics with complementary experimental readouts, supporting multi-modal analyses of cellular responses or biological processes.', 'cell microscopy, cellular imaging, fluorescence cell imaging, fixed cell imaging, brightfield imaging, cell visualization', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 164);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Atomic Force Microscopy (AFM)', 'Atomic Force Microscopy (AFM) is a high-resolution scanning probe microscopy technique used to characterize the topographical, mechanical, and structural properties of biological samples at the nanoscale, including cell surfaces, biomolecules, and extracellular matrix components. This assay employs a cantilever tip to scan sample surfaces and measure interaction forces, enabling quantification of parameters such as surface roughness, elasticity, adhesion forces, and molecular-scale morphology. Samples are typically prepared on flat substrates (e.g., glass or mica) under controlled conditions, and data acquisition is performed in contact, non-contact, or tapping mode depending on sample characteristics. The resulting force-distance curves and topographic images are analyzed using specialized software to extract quantitative biophysical measurements linked to experimental metadata and associated datasets.', 'AFM, atomic force microscopy, nanoscale surface imaging, tip-sample interaction, surface stiffness, nanoindentation, topography mapping', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 165);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Fourier Transform Infrared Spectroscopy (FTIR)', 'Fourier Transform Infrared (FTIR) Spectroscopy is an analytical technique that measures the absorption of infrared light by molecular bonds within a sample, providing a characteristic spectral fingerprint that reflects the biochemical composition of biological materials, including proteins, lipids, carbohydrates, and nucleic acids. In this linked-data implementation, infrared spectra are acquired across a defined wavenumber range and the resulting absorbance or transmittance data are associated with corresponding sample metadata and experimental records to enable integrated downstream analysis. Spectral preprocessing steps typically include baseline correction, normalization, and noise reduction, followed by multivariate or chemometric analysis to extract biologically meaningful information from the high-dimensional spectral datasets.', 'FTIR spectroscopy, infrared spectroscopy, attenuated total reflectance, ATR-FTIR, molecular fingerprint, chemical bond analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 166);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Dendritic Cell Preparation', 'Dendritic cell (DC) preparation encompasses the isolation, differentiation, and characterization of dendritic cells from biological sources (such as peripheral blood monocytes or bone marrow precursors) for use in downstream immunological assays. This metadata-level assay record documents the procedural and experimental parameters associated with DC generation, including source material, culture conditions (e.g., cytokine cocktails such as GM-CSF and IL-4), maturation stimuli, and quality control metrics. Key variables tracked include cell viability, surface marker expression (e.g., CD11c, MHC II, CD80/CD86), and yield, typically assessed by flow cytometry. This record serves as a standardized reference for ensuring reproducibility and traceability of dendritic cell preparations used in subsequent functional or immunogenicity studies.', 'DC preparation, dendritic cell generation, monocyte-derived dendritic cells, MDDC, antigen-presenting cell prep, DC maturation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 167);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('TransCompR Cross-Species Computational Modeling', 'This assay employs cross-species computational modeling to integrate and analyze transcriptomic or other molecular data across multiple organisms, enabling the translation of biological findings between species. The TransCompR framework applies statistical and machine learning methods to identify conserved gene expression patterns, pathways, or regulatory relationships by linking datasets derived from different species. Data linkage procedures involve standardized preprocessing, normalization, and ortholog mapping steps to harmonize cross-species datasets prior to model training and validation. Results provide mechanistic insights into conserved biological responses and support the extrapolation of preclinical animal model findings to human biology.', 'TransCompR modeling, cross-species computational model, species transcriptome translation, comparative model, trans-species modeling', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 168);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Immunopeptidomics', 'Immunopeptideomics is a mass spectrometry-based assay designed to identify and characterize peptides presented by major histocompatibility complex (MHC) molecules on the surface of cells, providing insight into the immunopeptidome relevant to antigen presentation and immune recognition. The workflow typically involves immunoaffinity purification of MHC-peptide complexes from cell lysates, followed by peptide elution, cleanup, and analysis by liquid chromatography-tandem mass spectrometry (LC-MS/MS). Resulting spectral data are processed through bioinformatic pipelines for peptide identification, quantification, and annotation, with datasets linked to associated experimental or clinical metadata to enable integrative analysis. This assay is commonly applied in the context of cancer immunology, vaccine development, and autoimmune research to map naturally processed and presented epitopes.', 'immunopeptidomics, MHC-I MHC-II peptide, HLA peptide profiling, antigen presentation, neoantigen identification, immune peptide mass spec', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 169);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Targeted Cancer Gene Panel Sequencing (Oncopanel)', 'Oncopanel is a targeted next-generation sequencing (NGS) assay designed to detect somatic mutations, copy number alterations, and structural variants across a defined panel of cancer-relevant genes from tumor-derived nucleic acid samples. The assay employs hybridization-based capture or amplicon-based enrichment strategies followed by massively parallel sequencing to enable comprehensive genomic profiling of clinically actionable oncogenic alterations. Bioinformatic pipelines are applied to aligned sequencing data to identify single nucleotide variants (SNVs), insertions/deletions (indels), gene fusions, and copy number changes, with results interpreted in the context of established cancer driver genes and therapeutic targets.', 'oncopanel sequencing, cancer targeted NGS, tumor mutation profiling, cancer gene panel, somatic variant detection, oncology sequencing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 170);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Proximity Extension Assay (PEA)', 'The Proximity Extension Assay (PEA) is a high-multiplex immunoassay technology used to quantify protein biomarkers in biological samples, typically plasma or serum, by exploiting dual-antibody recognition coupled with DNA reporter extension. In this method, pairs of oligonucleotide-labeled antibodies bind simultaneously to their target protein', 'Olink PEA, proximity extension assay, protein biomarker quantification, Cq value, high-sensitivity protein panel', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 171);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Patient-Derived Xenograft (PDX) Cell Line Generation', 'Patient-derived xenograft (PDX) cell lines are established by engrafting primary human tumor tissue or cells into immunocompromised mice, enabling the propagation and maintenance of tumor heterogeneity in an in vivo context. This process involves the surgical implantation or injection of patient tumor specimens into suitable murine hosts, followed by serial passaging to generate stable PDX models that recapitulate the molecular and phenotypic characteristics of the original tumor. The resulting PDX cell lines serve as biologically relevant preclinical tools for downstream applications including drug efficacy testing, biomarker discovery, and translational cancer research in mouse model systems.', 'PDX model, patient xenograft cell line, tumor cell line generation, patient-derived tumor, xenograft cell culture', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 172);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('cDNA Synthesis', 'Reverse transcription of isolated RNA into complementary DNA (cDNA) is performed to enable downstream gene expression analyses such as quantitative PCR or RNA sequencing. Total RNA samples are converted to cDNA using reverse transcriptase enzymes, typically in the presence of oligo(dT) or random hexamer primers, dNTPs, and appropriate buffer conditions. The resulting cDNA library serves as a stable, amplifiable template that accurately reflects the RNA transcriptome of the biological sample at the time of collection.', 'reverse transcription, cDNA synthesis, first-strand synthesis, RNA to DNA conversion, RT, complementary DNA preparation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 173);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Library Preparation', 'This assay encompasses the procedural and contextual metadata associated with nucleic acid extraction and sequencing library preparation workflows, capturing key parameters such as sample identifiers, extraction methods, reagent lots, instrument configurations, and quality control metrics. It serves as a structured record to ensure traceability and reproducibility across upstream sample processing steps prior to downstream sequencing or analytical pipelines. The metadata framework supports standardization of laboratory practices by documenting critical variables — including input material type, extraction platform, library construction chemistry, and yield/quality measurements — that influence data interpretation and inter-sample comparability.', 'library preparation, sequencing library, adapter ligation, Nextera library, NGS library, fragmentation library prep', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 174);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('FC Receptor Binding Analysis', 'This assay evaluates the binding interactions between immunoglobulin Fc regions and Fc receptors (FcRs), providing quantitative characterization of antibody-receptor engagement relevant to effector function assessment. Binding affinities, kinetics, or relative binding levels are measured using established ligand-binding or biophysical methodologies, which may include surface plasmon resonance (SPR), enzyme-linked immunosorbent assay (ELISA)-based platforms, or flow cytometry-based approaches depending on the experimental context. Data from this assay are linked to associated datasets, enabling cross-referential analysis of Fc receptor binding profiles across multiple antibody variants or sample conditions. Results support the characterization of antibody functionality, including ADCC, ADCP, and CDC pathway engagement, and inform structure-activity relationships for therapeutic antibody development.', 'Fc receptor binding analysis, FcR binding analysis, Fc-gamma receptor binding, antibody effector function, receptor affinity analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 177);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('High Resolution Mass Spectra Analysis', 'High-resolution mass spectrometry (HRMS) assay for the accurate determination of molecular masses and elemental compositions of chemical compounds, providing precise m/z measurements with high mass accuracy. This assay employs high-resolution mass spectrometric instrumentation to acquire full-scan or targeted mass spectral data, enabling unambiguous molecular formula confirmation and structural characterization of analytes. Data are linked to associated experimental records, supporting compound identification, purity assessment, and quality control workflows within the research pipeline.', 'HRMS analysis, accurate mass analysis, molecular formula confirmation, high-resolution MS data processing', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 181);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('SureQuant Analysis', 'SureQuant is a targeted mass spectrometry-based quantification assay that employs isotopically labeled internal standard peptides to trigger data-dependent acquisition of endogenous target peptides, enabling precise and reproducible absolute or relative protein quantification from biological samples. The method utilizes a two-channel detection strategy in which a known quantity of heavy-labeled standard peptides is used to dynamically schedule and normalize the acquisition of corresponding light endogenous peptides, thereby reducing variability and improving quantitative accuracy. Sample preparation typically involves protein extraction, enzymatic digestion (e.g., trypsin), and optional enrichment steps prior to LC-MS/MS analysis on high-resolution instruments such as the Orbitrap platform. Data analysis integrates peak area ratios between endogenous and internal standard peptides to derive quantitative measurements across experimental conditions.', 'SureQuant, targeted proteomics, heavy-labeled standard peptide, IS-PRM, triggered data-dependent acquisition, internal standard quantification, Orbitrap targeted MS', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 182);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Luminex Data Processing', 'Luminex-based multiplex immunoassay for the simultaneous quantitative detection of multiple analytes (such as cytokines, chemokines, or other soluble biomarkers) in biological samples using fluorescently encoded microspheres coupled to capture antibodies. Samples are incubated with the bead mixture, followed by biotinylated detection antibodies and streptavidin-phycoerythrin reporter, with data acquired on a Luminex flow cytometry-based instrument (e.g., MAGPIX, FLEXMAP 3D, or Luminex 200). Raw median fluorescence intensity (MFI) values are collected and processed against a standard curve to derive quantitative analyte concentrations, with quality control metrics applied to ensure assay validity. Data files are attached for downstream statistical analysis and interpretation.', 'Luminex data processing, multiplex immunoassay processing, MFI to concentration, cytokine quantification, Luminex plate analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 183);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Western Blot Analysis', 'Western blot analysis is a widely used immunodetection technique that enables the identification and semi-quantitative assessment of specific proteins within complex biological samples based on molecular weight separation. Protein samples are first denatured and resolved by sodium dodecyl sulfate-polyacrylamide gel electrophoresis (SDS-PAGE), then transferred onto a nitrocellulose or PVDF membrane, where target proteins are detected using primary antibodies specific to the protein of interest followed by enzyme-conjugated secondary antibodies and chemiluminescent or colorimetric visualization. Band intensities are typically quantified by densitometry using imaging software, with results normalized to a housekeeping protein (e.g., β-actin, GAPDH, or tubulin) to account for differences in sample loading. This method is commonly employed to assess protein expression levels, post-translational modifications, and protein integrity across experimental conditions.', 'western blot analysis, immunoblot analysis, SDS-PAGE analysis, densitometry, protein expression analysis, WB quantification, chemiluminescent blot analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 184);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('Comet Chip Analysis', 'The Comet Chip assay is a high-throughput adaptation of the single-cell gel electrophoresis (comet assay) technique used to quantify DNA damage and repair capacity at the individual cell level. In this method, cells are immobilized in an array of microwells on a functionalized surface, embedded in agarose, lysed, and subjected to alkaline or neutral electrophoresis to allow migration of damaged DNA fragments away from the nucleus. The resulting "comet" images are captured via fluorescence microscopy and analyzed using dedicated software to measure parameters such as percent tail DNA, tail moment, and tail length, which reflect the extent of DNA strand breaks. This platform enables simultaneous analysis of hundreds to thousands of individual cells per chip, improving statistical robustness and throughput compared to conventional comet assay formats.', 'comet chip analysis, DNA damage quantification, tail length analysis, tail moment analysis, comet image analysis, genotoxicity analysis', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 185);
INSERT INTO `assay_context` (`assay_name`, `Description`, `Tags`, `Alternative_Assay_Names`, `Required_Parent_Sample_Types`, `Optional_Parent_Sample_Types`, `Children_Sample_Types`, `Parent_Clade_Type`, `Child_Clade_Type`, `AssaySheet_Link`, `AssociatedRepository`, `Critical_Attributes`, `Protocols_Phrases`, `Protocols_UIDs`, `internal_assay_id`) VALUES ('ADFP Analysis', 'Antibody-Dependent Functional Profiling (ADFP) is a multiplexed systems serology approach that quantifies the capacity of antigen-specific antibodies to engage Fc receptors and activate diverse innate immune effector functions. The assay simultaneously measures multiple antibody-dependent activities — including phagocytosis (ADCP, ADNP), complement deposition (ADCD), and NK cell activation (ADNKA) — providing a comprehensive functional fingerprint of the humoral immune response. Antigen-coupled beads or immune complexes are incubated with effector cells or complement components, and downstream readouts (fluorescent bead uptake, complement fragment deposition, cytokine/degranulation markers) are captured via flow cytometry or Luminex-based detection. Results are typically reported as phagocytic scores, percent positive cells, or median fluorescence intensity, enabling comparative profiling across vaccine regimens, infection states, or treatment groups. Data linked to corresponding experimental metadata for integrated analysis.', 'antibody-dependent functional profiling analysis, ADFP, systems serology analysis, Fc effector function analysis, humoral immune profiling analysis, multiplexed functional readout', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 186);
